/* -*- coding: utf-8 -*- */

#include "app.h"

#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <string>

#include "cmdline.h"
#include "json.h"
#include "task.h"
#include "trace.h"
#include "util.h"

static const char VERSION_STR[] = "0.0";

//--------------------------------------------------------------------------------
app::app() {
	m_abort = false;
}

//--------------------------------------------------------------------------------
app::~app() {
}

//--------------------------------------------------------------------------------
int app::run(int argc, char *argv[]) {
	if(parse_options(argc, argv, &m_param) != 0) {
		return -1;
	}

    task reporter(std::bind(&app::report, this), 1000);
    reporter.start();

	m_monitor = std::make_unique<monitor>();

	while(!m_abort) {
		m_monitor->run();
	}

    reporter.stop();

	return 0;
}

//--------------------------------------------------------------------------------
int app::stop() {
	m_abort = true;

	return 0;
}

//--------------------------------------------------------------------------------
std::string app::status() {
	std::string s;

	return s;
}

//--------------------------------------------------------------------------------
void app::report() {
	std::cerr << "+" << std::endl;
}

//--------------------------------------------------------------------------------
int app::parse_options(int argc, char *argv[], app::param *p) {
	cmdline::parser cp;

	cp.add<int>("debug", 'd', "debug log level", false, 1);
	cp.add<std::string>("name", 'n', "identity name", false, "");
	cp.add("version", 'v', "show version");

	cp.parse_check(argc, argv);

	if(cp.exist("version")) {
		version(argv, VERSION_STR);
		return -1;
	}

	p->debug_level = cp.get<int>("debug");
	p->id_name     = cp.exist("name") ? cp.get<std::string>("name") : std::to_string(getpid());

	std::fprintf(stderr, "id_name: %s\n", p->id_name.c_str());
	std::fprintf(stderr, "debug_level: %d\n", p->debug_level);

	set_trace_id(p->id_name.c_str());
	set_trace_level(p->debug_level);

	return 0;
}

//--------------------------------------------------------------------------------
void app::version(char *argv[], const char *ver) {
	std::fprintf(stderr, "%s\n", ver);
}

