#include "monitor.h"

#include <iostream>
#include <memory>

#include "trace.h"
#include "tsv.h"
#include "tsv_util.h"

monitor::monitor() {
}

monitor::~monitor() {
}

int monitor::run() {
    {
	    std::ios::sync_with_stdio(false);
	    std::cin.tie(nullptr);
    }

	// ctx mc {
	// 	.log = std::make_unique<logger>("", "", 0, 0)
	// };

    m_srt   = std::make_unique<srt::streams>();
    m_rtp   = std::make_unique<rtp::streams>();
    m_hls   = std::make_unique<hls::streams>();
    m_other = std::make_unique<other::streams>();

	tsv::ctx tc;
    tsv::row_t row;
    std::string line;

    if(std::getline(std::cin, line)) {
	    tsv::init_ctx(tc, line);
    }

    while(std::getline(std::cin, line)) {
	    std::lock_guard<std::mutex> lock(m_mutex);

	    row.clear();
	    tsv::split(line, row);

	    std::string_view proto = row[tc.i.com.proto];
	    if(proto == "SRT") {
		    m_srt->process(tc, row);
	    }
	    else if((proto == "MPEG TS") || (proto == "RTP")) {
		    m_rtp->process(tc, row);
	    }
	    else if(proto == "HTTP") {
		    m_hls->process(tc, row);
	    }
	    else {
		    m_other->process(tc, row);
	    }
    }

    return 0;
}

int monitor::stop() {
	return 0;
}

void monitor::report() {
	{
		std::lock_guard<std::mutex> lock(m_mutex);
	}
}

#ifndef STREAMS_H
#define STREAMS_H

#include "tsv.h"
#include <ctime>

class expirable {
public:
    expirable() = default;
    virtual ~expirable() = default;

    void touch(double now) noexcept {
        m_last_seen = now;
        m_seen = true;
    }

    double last_seen() const noexcept {
        return m_last_seen;
    }

    bool seen() const noexcept {
        return m_seen;
    }

    bool expired(double now, double timeout_sec) const noexcept {
        return m_seen && (now - m_last_seen) >= timeout_sec;
    }

private:
    double m_last_seen = 0.0;
    bool   m_seen = false;
};

class streams {
public:
	virtual ~streams() = default;

	virtual int process(tsv::ctx &c, const tsv::row_t &row) = 0;
	virtual int report() = 0;
};

#endif /* STREAMS_H */

