#ifndef VALUE_H
#define VALUE_H

struct value {
    uint64_t count = 0;
    double sum = 0.0;
    double min = 0.0;
    double max = 0.0;
    double last = 0.0;
    bool has_value = false;

    void add(double v) {
        if(!has_value) {
            min = max = last = v;
            sum = v;
            count = 1;
            has_value = true;
            return;
        }
        if(v < min) {
	        min = v;
        }
        if(v > max) {
	        max = v;
        }
        last = v;
        sum += v;
        ++count;
    }

    double avg() const {
        return count ? (sum / static_cast<double>(count)) : 0.0;
    }

    void clear() {
        *this = value{};
    }
};

#endif /* VALUE_H */

