inline field_map_t make_field_map(const std::string &header_line) {
	field_map_t map;

	std::stringstream ss(header_line);
	std::string field;
	int index = 0;

	while(std::getline(ss, field, '\t')) {
		map[field] = index++;
	}

	return map;
}

