#ifndef METRICS_COMMON_H
#define METRICS_COMMON_H

#include <cstdint>
#include <cmath>
#include <limits>

class counter {
public:
    struct result {
        std::uint64_t count{0};
    };

public:
    void reset() {
        count_ = 0;
    }

    void inc() {
        ++count_;
    }

    void add(std::uint64_t n) {
        count_ += n;
    }

    void add(bool cond) {
        if (cond) {
            ++count_;
        }
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    result value() const {
        return result{ .count = count_ };
    }

private:
    std::uint64_t count_{0};
};

class value_stats {
public:
    struct result {
        std::uint64_t count{0};
        double min{0.0};
        double max{0.0};
        double avg{0.0};
        double stddev{0.0};
        double sum{0.0};
    };

public:
    void reset() {
        count_ = 0;
        sum_ = 0.0;
        mean_ = 0.0;
        m2_ = 0.0;
        min_ = std::numeric_limits<double>::max();
        max_ = std::numeric_limits<double>::lowest();
    }

    void add(double v) {
        if (count_ == 0) {
            count_ = 1;
            sum_ = v;
            mean_ = v;
            m2_ = 0.0;
            min_ = v;
            max_ = v;
            return;
        }

        ++count_;
        sum_ += v;

        if (v < min_) min_ = v;
        if (v > max_) max_ = v;

        const double delta = v - mean_;
        mean_ += delta / static_cast<double>(count_);
        const double delta2 = v - mean_;
        m2_ += delta * delta2;
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    double sum() const {
        return sum_;
    }

    double min() const {
        return count_ ? min_ : 0.0;
    }

    double max() const {
        return count_ ? max_ : 0.0;
    }

    double avg() const {
        return count_ ? mean_ : 0.0;
    }

    double variance() const {
        return count_ ? (m2_ / static_cast<double>(count_)) : 0.0;
    }

    double stddev() const {
        return std::sqrt(variance());
    }

    result value() const {
        return result{
            .count = count_,
            .min = min(),
            .max = max(),
            .avg = avg(),
            .stddev = stddev(),
            .sum = sum_,
        };
    }

private:
    std::uint64_t count_{0};
    double sum_{0.0};

    double mean_{0.0};
    double m2_{0.0};

    double min_{std::numeric_limits<double>::max()};
    double max_{std::numeric_limits<double>::lowest()};
};

class interval {
public:
    struct result {
        bool updated{false};
        double interval_sec{0.0};
    };

public:
    void reset() {
        initialized_ = false;
        prev_time_ = 0.0;
    }

    result update(double time_epoch) {
        result r{};

        if (!initialized_) {
            initialized_ = true;
            prev_time_ = time_epoch;
            return r;
        }

        const double interval = time_epoch - prev_time_;
        prev_time_ = time_epoch;

        if (interval < 0.0) {
            return r;
        }

        r.updated = true;
        r.interval_sec = interval;
        return r;
    }

private:
    bool initialized_{false};
    double prev_time_{0.0};
};

class sequence_stats {
public:
    struct update_result {
        bool updated{false};
        std::uint64_t seq{0};

        bool duplicate{false};
        bool reordered{false};
        std::uint64_t gap_added{0};
    };

public:
    void reset() {
        initialized_ = false;
        last_seq_ = 0;
        gap_count_.reset();
        reorder_count_.reset();
        dup_count_.reset();
    }

    void reset_stats() {
        gap_count_.reset();
        reorder_count_.reset();
        dup_count_.reset();
    }

    update_result update(std::uint64_t seq) {
        update_result r{};
        r.updated = true;
        r.seq = seq;

        if (!initialized_) {
            initialized_ = true;
            last_seq_ = seq;
            return r;
        }

        if (seq == last_seq_) {
            dup_count_.inc();
            r.duplicate = true;
            return r;
        }

        if (seq == last_seq_ + 1) {
            last_seq_ = seq;
            return r;
        }

        if (seq > last_seq_ + 1) {
            const std::uint64_t gap = seq - last_seq_ - 1;
            gap_count_.add(gap);
            r.gap_added = gap;
            last_seq_ = seq;
            return r;
        }

        reorder_count_.inc();
        r.reordered = true;
        return r;
    }

    const counter& gap_count() const {
        return gap_count_;
    }

    const counter& reorder_count() const {
        return reorder_count_;
    }

    const counter& dup_count() const {
        return dup_count_;
    }

    std::uint64_t last_seq() const {
        return last_seq_;
    }

    bool initialized() const {
        return initialized_;
    }

private:
    bool initialized_{false};
    std::uint64_t last_seq_{0};

    counter gap_count_;
    counter reorder_count_;
    counter dup_count_;
};

class bitrate {
public:
    struct result {
        bool updated{false};   // 今回の入力でビットレートが更新されたか
        double bps{0.0};       // bits per second
        double elapsed{0.0};   // 前回更新からの経過秒
    };

public:
    void reset() {
        current_time_ = -1.0;
        rec_bytes_ = 0;
        bitrate_bps_ = 0.0;
    }

    result update(double time_epoch, std::uint64_t frame_len) {
        result r{};

        if (current_time_ < 0.0) {
            current_time_ = time_epoch;
        }

        const std::int64_t now_sec = static_cast<std::int64_t>(time_epoch);
        const std::int64_t cur_sec = static_cast<std::int64_t>(current_time_);

        if (now_sec > cur_sec) {
            const double elapsed = time_epoch - current_time_;

            if (elapsed > 0.0) {
                bitrate_bps_ = static_cast<double>(rec_bytes_) * 8.0 / elapsed;
                r.updated = true;
                r.bps = bitrate_bps_;
                r.elapsed = elapsed;
            }

            current_time_ = time_epoch;
            rec_bytes_ = 0;
        }

        rec_bytes_ += frame_len;
