}

int monitor::run() {
    {
	    std::ios::sync_with_stdio(false);
	    std::cin.tie(nullptr);
    }

	// ctx mc {
	// 	.log = std::make_unique<logger>("", "", 0, 0)
	// };

    m_srt   = std::make_unique<srt::streams>();
    m_rtp   = std::make_unique<rtp::streams>();
    m_hls   = std::make_unique<hls::streams>();
    m_other = std::make_unique<other::streams>();

    std::unordered_map<std::string_view, streams*> dispatcher = {
	    { "SRT",     m_srt.get() },
	    { "MPEG TS", m_rtp.get() },
	    { "RTP",     m_rtp.get() },
	    { "HTTP",    m_hls.get() },
    };

    m_writer = std::make_unique<writer>();

	tsv::ctx tc;
    tsv::row_t row;
    std::string line;

    if(std::getline(std::cin, line)) {
	    tsv::init_ctx(tc, line);
    }

    while(std::getline(std::cin, line)) {
	    row.clear();
	    tsv::split(line, row);

	    std::string_view proto = row[tc.i.com.proto];
	    tsv::to_number(row[tc.i.com.time_epoch], tc.r.com.time_epoch);

	    auto it = dispatcher.find(proto);
	    if(it != dispatcher.end()) {
		    it->second->process(tc, row);
	    }
	    else {
		    m_other->process(tc, row);
	    }

	    auto br = m_second_boundary.update(tc.r.com.time_epoch);
	    if(br.changed) {
		    for(auto& [proto, stream] : dispatcher) {
			    stream->flush_metrics(tc.r.com.time_epoch, *m_writer);
		    }
		    m_other->flush_metrics(tc.r.com.time_epoch, *m_writer);
		    // reset_stats();
	    }
    }

    return 0;
}

int monitor::stop() {
	return 0;
}

