#ifndef STREAM_SRT_H
#define STREAM_SRT_H

#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>

#include "endpoint.h"
#include "metrics_common.h"
#include "streams.h"
#include "tsv.h"

namespace srt {

struct info {
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
	uint8_t  iscontrol;
	uint16_t type;
	uint32_t seqno;
	uint8_t  msg_rexmit;
	uint32_t msg_order;
	uint32_t nak_seqno;
	uint32_t rtt;
	uint32_t rttvar;
	uint32_t rate;
	uint32_t rcvrate;
	uint32_t bw;
	uint32_t timestamp;
	std::string hs_sid;
};

struct stream_id {
    ip_endpoint endpoint_a;
    ip_endpoint endpoint_b;
    std::string streamid;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_a));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_b));
        hash_combine(h, std::hash<std::string>{}(v.streamid));
        return h;
    }
};

struct flow_id {
    ip_endpoint src;
    ip_endpoint dst;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        return h;
    }
};

inline stream_id make_stream_id(
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port,
    std::string_view streamid_sv
) {
    auto ep = normalize_endpoints(src_ip, src_port, dst_ip, dst_port);
    return stream_id{
        .endpoint_a = std::move(ep.a),
        .endpoint_b = std::move(ep.b),
        .streamid = std::string(streamid_sv)
    };
}

inline flow_id make_flow_id(
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    return flow_id{
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port}
    };
}

struct flow_metrics {
	metrics::bitrate        bitrate;
	metrics::interval       interval;
	metrics::sequence_stats seq_stats;
	metrics::value_stats    rtt;
	// metrics::rtp::jitter             jitter;
    // metrics::rtp::clock_skew         skew;
    // metrics::rtp::seq_extender       seq_ext;
    // metrics::rtp::timestamp_extender ts_ext;
};

class flow
	: public expirable {
public:
	flow(const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);

private:
	flow_id m_fid;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	void expire_flows(double now);
	bool empty() { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int flush_metrics(double now, writer &w) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_streams(double now);
};

static constexpr double k_flow_idle_timeout_sec = 10.0;
static constexpr double k_stream_idle_timeout_sec = 30.0;

} // namespace srt

#endif /* STREAM_SRT_H */

