#ifndef METRICS_COMMON_H
#define METRICS_COMMON_H

#include <cstdint>
#include <cmath>
#include <limits>

#include <iostream>

namespace metrics {

class counter {
public:
    struct result {
        std::uint64_t count{0};
    };

public:
    void reset() {
        count_ = 0;
    }

    void inc() {
        ++count_;
    }

    void add(std::uint64_t n) {
        count_ += n;
    }

    void add(bool cond) {
        if (cond) {
            ++count_;
        }
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    result value() const {
        return result{ .count = count_ };
    }

private:
    std::uint64_t count_{0};
};

struct value_stats {
    std::uint64_t count{0};
    double sum{0.0};
    double min{0.0};
