class clock_skew {
public:
    struct result {
        bool updated{false};
        double elapsed_sec{0.0};
        double observed_rate{0.0};
        double skew_ppm{0.0};
        double skew_ratio{0.0};
    };

public:
    explicit clock_skew(std::uint32_t clock_rate = 90000)
        : clock_rate_(clock_rate) {}

    void reset_window() {
        initialized_ = false;
        base_arrival_sec_ = 0.0;
        base_ext_ts_ = 0;
        observed_rate_ = 0.0;
        skew_ppm_ = 0.0;
        skew_ratio_ = 0.0;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    void set_clock_rate(std::uint32_t clock_rate) {
        clock_rate_ = clock_rate;
    }

    result update(double arrival_sec, std::uint64_t ext_rtp_ts) {
        result r{};

        if (clock_rate_ == 0) {
            return r;
        }

        if (!initialized_) {
            initialized_ = true;
            base_arrival_sec_ = arrival_sec;
            base_ext_ts_ = ext_rtp_ts;
            return r;
        }

        elapsed_sec_ = arrival_sec - base_arrival_sec_;
        if (elapsed_sec_ <= 0.0) {
            return r;
        }

        const std::uint64_t elapsed_ts_u64 = ext_rtp_ts - base_ext_ts_;
        const double elapsed_ts = static_cast<double>(elapsed_ts_u64);

        observed_rate_ = elapsed_ts / elapsed_sec_;
        skew_ratio_ = observed_rate_ / static_cast<double>(clock_rate_) - 1.0;
        skew_ppm_ = skew_ratio_ * 1.0e6;

        stats_.add(skew_ppm_);

        r.updated = true;
        r.elapsed_sec = elapsed_sec_;
        r.observed_rate = observed_rate_;
        r.skew_ppm = skew_ppm_;
        r.skew_ratio = skew_ratio_;
        return r;
    }

    double observed_rate() const { return observed_rate_; }
    double skew_ppm() const { return skew_ppm_; }
    double skew_ratio() const { return skew_ratio_; }
    double elapsed_sec() const { return elapsed_sec_; }

    const value_stats& stats() const {
        return stats_;
    }

private:
    std::uint32_t clock_rate_{90000};
    bool initialized_{false};
    double base_arrival_sec_{0.0};
    std::uint64_t base_ext_ts_{0};
    double observed_rate_{0.0};
    double skew_ppm_{0.0};
    double skew_ratio_{0.0};
    double elapsed_sec_{0.0};
    value_stats stats_{};
};

}

