			{"control", m.packet_counts.control().count()},
			{"retransmit", m.packet_counts.retransmit().count()},
		}},
		{"control_type_count", {
			{"total", m.control_types.total().count()},
			{"handshake", m.control_types.handshake().count()},
			{"keepalive", m.control_types.keepalive().count()},
			{"ack", m.control_types.ack().count()},
			{"nak", m.control_types.nak().count()},
			{"shutdown", m.control_types.shutdown().count()},
			{"ackack", m.control_types.ackack().count()},
			{"dropreq", m.control_types.dropreq().count()},
			{"peer_error", m.control_types.peer_error().count()},
			{"user_defined", m.control_types.user_defined().count()},
			{"other", m.control_types.other().count()},
		}},
		{"count", {
			{"gap", m.seq_stats.gap_count().count()},
			{"dup", m.seq_stats.dup_count().count()},
			{"reorder", m.seq_stats.reorder_count().count()},
		}},
		{"rtt", {
			{"value", m.rtt.value()},
			{"count", m.rtt.stats().count},
			{"min", m.rtt.stats().min},
			{"max", m.rtt.stats().max},
			{"avg", m.rtt.stats().avg()},
		}},
		{"rttvar", {
			{"value", m.rttvar.value()},
			{"count", m.rttvar.stats().count},
			{"min", m.rttvar.stats().min},
			{"max", m.rttvar.stats().max},
			{"avg", m.rttvar.stats().avg()},
		}},
		{"rate", {
			{"value", m.rate.value()},
			{"count", m.rate.stats().count},
			{"min", m.rate.stats().min},
			{"max", m.rate.stats().max},
			{"avg", m.rate.stats().avg()},
		}},
		{"rcvrate", {
			{"value", m.rcvrate.value()},
			{"count", m.rcvrate.stats().count},
			{"min", m.rcvrate.stats().min},
			{"max", m.rcvrate.stats().max},
			{"avg", m.rcvrate.stats().avg()},
		}},
		{"bandwidth", {
			{"value", m.bw.value()},
			{"count", m.bw.stats().count},
			{"min", m.bw.stats().min},
			{"max", m.bw.stats().max},
			{"avg", m.bw.stats().avg()},
		}},
		{"nak_seqno", {
			{"count", m.nak_seq_stats.count},
			{"min", m.nak_seq_stats.min},
			{"max", m.nak_seq_stats.max},
			{"avg", m.nak_seq_stats.avg()},
		}},
	};

	m.bitrate.clear_stats();
	m.interval.clear_stats();
	m.seq_stats.reset_stats();
	m.nak_seq_stats.clear();
	m.packet_counts.reset();
	m.control_types.reset();
	m.rtt.clear_stats();
	m.rttvar.clear_stats();
	m.rate.clear_stats();
	m.rcvrate.clear_stats();
	m.bw.clear_stats();

	std::fprintf(stderr, "%s\n", j.dump(2).c_str());

	return 0;
}

stream::stream(const stream_id sid)
