class control_packet_type_counter {
public:
    void reset() {
        total_.reset();
        handshake_.reset();
        keepalive_.reset();
        ack_.reset();
        nak_.reset();
        shutdown_.reset();
        ackack_.reset();
        dropreq_.reset();
        peer_error_.reset();
        user_defined_.reset();
        other_.reset();
    }

    void update(std::uint16_t type) {
        total_.inc();

        switch(type) {
        case 0x0000: handshake_.inc(); break;
        case 0x0001: keepalive_.inc(); break;
        case 0x0002: ack_.inc(); break;
        case 0x0003: nak_.inc(); break;
        case 0x0004: shutdown_.inc(); break;
        case 0x0006: ackack_.inc(); break;
        case 0x0007: dropreq_.inc(); break;
        case 0x0008: peer_error_.inc(); break;
        case 0x7fff: user_defined_.inc(); break;
        default: other_.inc(); break;
        }
    }

    const counter& total() const { return total_; }
    const counter& handshake() const { return handshake_; }
    const counter& keepalive() const { return keepalive_; }
    const counter& ack() const { return ack_; }
    const counter& nak() const { return nak_; }
    const counter& shutdown() const { return shutdown_; }
    const counter& ackack() const { return ackack_; }
    const counter& dropreq() const { return dropreq_; }
    const counter& peer_error() const { return peer_error_; }
    const counter& user_defined() const { return user_defined_; }
    const counter& other() const { return other_; }

private:
    counter total_{};
    counter handshake_{};
    counter keepalive_{};
    counter ack_{};
    counter nak_{};
    counter shutdown_{};
    counter ackack_{};
    counter dropreq_{};
    counter peer_error_{};
    counter user_defined_{};
    counter other_{};
};

class packet_counters {
public:
    void reset() {
        total_.reset();
        data_.reset();
        control_.reset();
        retransmit_.reset();
    }

    void update(bool is_control, bool is_retransmit) {
        total_.inc();
        if(is_control) {
            control_.inc();
        }
        else {
            data_.inc();
        }
        if(is_retransmit) {
            retransmit_.inc();
        }
    }

    const counter& total() const { return total_; }
    const counter& data() const { return data_; }
    const counter& control() const { return control_; }
    const counter& retransmit() const { return retransmit_; }

private:
    counter total_{};
    counter data_{};
    counter control_{};
    counter retransmit_{};
};

class gauge {
public:
    void reset() {
        has_value_ = false;
        last_value_ = 0.0;
        stats_.clear();
    }

    void update(double value) {
        has_value_ = true;
        last_value_ = value;
        stats_.add(value);
    }

    bool has_value() const { return has_value_; }
    double value() const { return last_value_; }
    const value_stats& stats() const { return stats_; }

    void clear_stats() {
        stats_.clear();
    }

private:
    bool has_value_{false};
    double last_value_{0.0};
    value_stats stats_{};
};

