struct value_stats {
    std::uint64_t count{0};
    double sum{0.0};
    double min{0.0};
    double max{0.0};

    // 分散計算用
    double mean{0.0};
    double m2{0.0};

    void clear() {
        count = 0;
        sum = 0.0;
        min = 0.0;
        max = 0.0;
        mean = 0.0;
        m2 = 0.0;
    }

    void add(double v) {
        if (count == 0) {
            min = max = v;
        } else {
            if (v < min) min = v;
            if (v > max) max = v;
        }

        sum += v;
        ++count;

        const double delta = v - mean;
        mean += delta / static_cast<double>(count);
        const double delta2 = v - mean;
        m2 += delta * delta2;
    }

