#ifndef METRICS_COMMON_H
#define METRICS_COMMON_H

#include <cstdint>
#include <cmath>
#include <limits>

#include <iostream>

namespace metrics {

class counter {
public:
    struct result {
        std::uint64_t count{0};
    };

public:
    void reset() {
        count_ = 0;
    }

    void inc() {
        ++count_;
    }

    void add(std::uint64_t n) {
        count_ += n;
    }

    void add(bool cond) {
        if (cond) {
            ++count_;
        }
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    result value() const {
        return result{ .count = count_ };
    }

private:
    std::uint64_t count_{0};
};

struct value_stats {
    std::uint64_t count{0};
    double sum{0.0};
    double min{0.0};
    double max{0.0};

    // 分散計算用
    double mean{0.0};
    double m2{0.0};

    void clear() {
        count = 0;
        sum = 0.0;
        min = 0.0;
        max = 0.0;
        mean = 0.0;
        m2 = 0.0;
    }

    void add(double v) {
        if (count == 0) {
            min = max = v;
        } else {
            if (v < min) min = v;
            if (v > max) max = v;
        }

        sum += v;
        ++count;

        const double delta = v - mean;
        mean += delta / static_cast<double>(count);
        const double delta2 = v - mean;
        m2 += delta * delta2;
    }

    bool empty() const {
        return count == 0;
    }

    double avg() const {
        return count ? mean : 0.0;
    }

    // 母分散
    double variance() const {
        return count ? (m2 / static_cast<double>(count)) : 0.0;
    }

    // 母標準偏差
    double stddev() const {
        return std::sqrt(variance());
    }

    // 不偏分散
    double sample_variance() const {
        return (count > 1) ? (m2 / static_cast<double>(count - 1)) : 0.0;
    }

    // 不偏標準偏差
    double sample_stddev() const {
        return std::sqrt(sample_variance());
    }
};

class gauge {
public:
    void reset() {
        has_value_ = false;
        last_value_ = 0.0;
        stats_.clear();
    }

    void update(double value) {
        has_value_ = true;
        last_value_ = value;
        stats_.add(value);
    }

    bool has_value() const { return has_value_; }
    double value() const { return last_value_; }
    const value_stats& stats() const { return stats_; }

    void clear_stats() {
        stats_.clear();
    }

private:
    bool has_value_{false};
    double last_value_{0.0};
    value_stats stats_{};
};

class interval {
public:
    struct result {
        bool updated{false};
        double seconds{0.0};
    };

public:
    void reset_window() {
        prev_time_ = -1.0;
        interval_sec_ = 0.0;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch) {
        result r{};

        if (prev_time_ >= 0.0) {
            const double d = time_epoch - prev_time_;
            if (d >= 0.0) {
                interval_sec_ = d;
                stats_.add(interval_sec_);

                r.updated = true;
                r.seconds = interval_sec_;
            }
        }

        prev_time_ = time_epoch;
        return r;
    }

    double value() const { return interval_sec_; }
    const value_stats& stats() const { return stats_; }

private:
    double prev_time_{-1.0};
    double interval_sec_{0.0};
    value_stats stats_{};
};

class sequence_stats {
public:
    struct update_result {
        bool updated{false};
