	tsv::to_number(row[c.i.srt.iscontrol],   i.iscontrol);
	tsv::to_number(row[c.i.srt.type],        i.type);
	tsv::to_number(row[c.i.srt.seqno],       i.seqno);
	tsv::to_number(row[c.i.srt.msg_rexmit],  i.msg_rexmit);
	tsv::to_number(row[c.i.srt.msg_order],   i.msg_order);
	tsv::to_number(row[c.i.srt.nak_seqno],   i.nak_seqno);
	tsv::to_number(row[c.i.srt.rtt],         i.rtt);
	tsv::to_number(row[c.i.srt.rttvar],      i.rttvar);
	tsv::to_number(row[c.i.srt.rate],        i.rate);
	tsv::to_number(row[c.i.srt.rcvrate],     i.rcvrate);
	tsv::to_number(row[c.i.srt.bw],          i.bw);
	tsv::to_number(row[c.i.srt.timestamp],   i.timestamp);
	tsv::to_string(row[c.i.srt.hs_sid],      i.hs_sid);

	return 0;
}

