#include "stream_hls.h"
#include "stream_other.h"
#include "stream_rtp.h"
#include "stream_srt.h"
#include "writer.h"

class monitor {
public:
	monitor();
	virtual ~monitor();

	int run();
	int stop();

	struct ctx {
		std::unique_ptr<logger> log;
	};

private:
	struct ctx m_ctx;
	std::unique_ptr<srt::streams> m_srt;
	std::unique_ptr<rtp::streams> m_rtp;
	std::unique_ptr<hls::streams> m_hls;
	std::unique_ptr<other::streams> m_other;
	std::unique_ptr<writer> m_writer;
	metrics::second_boundary m_second_boundary;
};

#endif /* MONITOR_H */

#ifndef STREAM_HLS_H
#define STREAM_HLS_H

#include <cstdint>
#include <string>
#include <memory>
#include <unordered_map>

#include "endpoint.h"
#include "streams.h"
#include "tsv.h"

namespace hls {

struct info {
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
};

struct stream_id {
    std::string playlist_url;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        return std::hash<std::string>{}(v.playlist_url);
    }
};

struct flow_id {
    std::string method;
    std::string host;
    std::uint16_t port{0};
    std::string path;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::string>{}(v.method));
        hash_combine(h, std::hash<std::string>{}(v.host));
        hash_combine(h, std::hash<std::uint16_t>{}(v.port));
        hash_combine(h, std::hash<std::string>{}(v.path));
        return h;
    }
};

inline stream_id make_stream_id(std::string_view playlist_url_sv) {
    return stream_id{
        .playlist_url = std::string(playlist_url_sv)
    };
}

inline flow_id make_flow_id(
    std::string_view method_sv,
    std::string_view host_sv,
    std::uint16_t port,
    std::string_view path_sv
) {
    return flow_id{
        .method = std::string(method_sv),
        .host   = std::string(host_sv),
        .port   = port,
        .path   = std::string(path_sv)
    };
}

class flow
	: public expirable {
public:
	flow(const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);

private:
	flow_id m_fid;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	void expire_flows(double now);
	bool empty() { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int flush_metrics(double now, writer &w) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_streams(double now);
};

static constexpr double k_flow_idle_timeout_sec = 10.0;
static constexpr double k_stream_idle_timeout_sec = 30.0;

} // namespace hls

#endif /* STREAM_HLS */

#ifndef STREAM_OTHER_H
#define STREAM_OTHER_H

#include <cstdint>
#include <memory>
#include <unordered_map>

#include "endpoint.h"
#include "streams.h"
#include "tsv.h"

namespace other {

struct info {
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
	uint8_t ip_proto;
	uint8_t ipv6_nxt;
};

struct stream_id {
    std::uint8_t ip_proto{0};
    ip_endpoint endpoint_a;
    ip_endpoint endpoint_b;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint8_t>{}(v.ip_proto));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_a));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_b));
        return h;
    }
};

struct flow_id {
    std::uint8_t ip_proto{0};
    ip_endpoint src;
    ip_endpoint dst;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint8_t>{}(v.ip_proto));
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        return h;
    }
};

inline stream_id make_stream_id(
    std::uint8_t ip_proto,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    auto ep = normalize_endpoints(src_ip, src_port, dst_ip, dst_port);
    return stream_id{
        .ip_proto   = ip_proto,
        .endpoint_a = std::move(ep.a),
        .endpoint_b = std::move(ep.b)
    };
}

inline flow_id make_flow_id(
    std::uint8_t ip_proto,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    return flow_id{
        .ip_proto = ip_proto,
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port}
    };
}

class flow
	: public expirable {
public:
	flow(const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);

private:
	flow_id m_fid;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);

	void expire_flows(double now);
	bool empty() const noexcept { return m_flows.empty(); }

    double first_seen = 0.0;
    double last_seen  = 0.0;

private:
	stream_id m_sid;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

struct pending_stream {
    double first_seen = 0.0;
    double last_seen  = 0.0;
    uint64_t packets  = 0;
    uint64_t bytes    = 0;

    void add(const info& i) {
        if (packets == 0) {
            first_seen = i.time_epoch;
        }
        last_seen = i.time_epoch;
        ++packets;
        bytes += i.frame_len;
    }
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int flush_metrics(double now, writer &w) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;
	std::unordered_map<stream_id, pending_stream, stream_id_hash> m_pending;

	uint64_t m_other_oneshot_flows   = 0;
	uint64_t m_other_oneshot_packets = 0;
	uint64_t m_other_oneshot_bytes   = 0;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_pending(double now);
	void expire_streams(double now);
};

static constexpr double k_pending_timeout_sec = 5.0;
static constexpr double k_flow_idle_timeout_sec = 10.0;
static constexpr double k_stream_idle_timeout_sec = 30.0;

} // namespace other

#endif /* STREAM_OTHER */

