namespace rtp {

flow::flow(const flow_id fid)
	: m_fid(std::move(fid))
	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst)) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		m_metrics.seq_stats.update(ex.ext_seq);
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

int flow::flush_metrics(double now, writer &w) {
	flow_metrics &m = m_metrics;

    json j{
		{"time", now},
	    {"proto", "RTP"},
	    {"endpoint",{
			    {"src",  m_src_text },
			    {"dst",  m_dst_text },
		    }},
		{"bitrate", {
			{"bps", m.bitrate.value()},
			{"count", m.bitrate.stats().count},
			{"min", m.bitrate.stats().min},
			{"max", m.bitrate.stats().max},
			{"avg", m.bitrate.stats().avg()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", m.seq_stats.gap_count().count()},
	        {"dup", m.seq_stats.dup_count().count()},
	        {"reorder", m.seq_stats.reorder_count().count()},
        }}
    };

    m.bitrate.clear_stats();
    m.interval.clear_stats();
    m.seq_stats.reset_stats();

    std::fprintf(stderr, "%s\n", j.dump(2).c_str());

	return w.dump(j);
}

stream::stream(const stream_id sid)
	: m_sid(std::move(sid)) {
}

int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid{
		.src = {i.src.addr, i.src.port},
		.dst = {i.dst.addr, i.dst.port}
	};

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(fid)).first;
	}

	return it->second->process(i);
}

int stream::flush_metrics(double now, writer &w) {
	for(auto& [fid, flow] : m_flows) {
		flow->flush_metrics(now, w);
	}

	return 0;
}

void stream::expire_flows(double now) {
    for(auto it = m_flows.begin(); it != m_flows.end(); ) {
        if (it->second->expired(now, k_flow_idle_timeout_sec)) {
            it = m_flows.erase(it);
        }
        else {
            ++it;
        }
    }
}

