namespace rtp {

flow::flow(const flow_id fid)
	: m_fid(std::move(fid))
	, m_role_text(to_string(m_fid.role))
	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst)) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		m_metrics.seq_stats.update(ex.ext_seq);
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	return json{
		{"role", m_role_text},
		{"ssrc", m_fid.ssrc},
		{"payload_type", m_fid.payload_type},
		{"endpoint", {
			{"src", m_src_text},
			{"dst", m_dst_text},
		}},
		{"last_seen", last_seen()},
	};
}

int flow::flush_metrics(double now, writer &w) {
	flow_metrics &m = m_metrics;

    json j{
		{"time", now},
	    {"proto", "RTP"},
	    {"role", m_role_text},
	    {"ssrc", m_fid.ssrc},
	    {"payload_type", m_fid.payload_type},
	    {"endpoint",{
			    {"src",  m_src_text },
			    {"dst",  m_dst_text },
		    }},
		{"bitrate", {
			{"bps", m.bitrate.value()},
			{"count", m.bitrate.stats().count},
			{"min", m.bitrate.stats().min},
			{"max", m.bitrate.stats().max},
			{"avg", m.bitrate.stats().avg()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", m.seq_stats.gap_count().count()},
	        {"dup", m.seq_stats.dup_count().count()},
	        {"reorder", m.seq_stats.reorder_count().count()},
        }}
    };

    m.bitrate.clear_stats();
    m.interval.clear_stats();
    m.seq_stats.reset_stats();

    std::fprintf(stderr, "%s\n", j.dump(2).c_str());

	return w.dump(j);
}

stream::stream(const stream_id sid)
	: m_sid(std::move(sid))
	, m_session_dst_text(to_string(m_sid.session_dst)) {
}

int stream::process(const flow_id &fid, const info &i) {
	touch(i.time_epoch);

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(fid)).first;
	}

	return it->second->process(i);
}

int stream::flush_metrics(double now, writer &w) {
	for(auto& [fid, flow] : m_flows) {
		flow->flush_metrics(now, w);
	}

	return 0;
}

int stream::flush_list(double now, writer &w) {
	json flows = json::array();
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}

	json j{
		{"time", now},
		{"proto", "RTP"},
		{"stream", {
			{"session_dst", m_session_dst_text},
			{"last_seen", last_seen()},
			{"flow_count", m_flows.size()},
			{"flows", std::move(flows)},
		}},
	};

	return w.dump(j);
}

void stream::expire_flows(double now) {
    for(auto it = m_flows.begin(); it != m_flows.end(); ) {
        if (it->second->expired(now, k_flow_idle_timeout_sec)) {
            it = m_flows.erase(it);
        }
        else {
            ++it;
        }
    }
}

streams::streams() {
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}

	expire_streams(i.time_epoch);

	stream_id sid;
	flow_id fid;
	resolve_ids(i, sid, fid);

	auto it = m_streams.find(sid);
	if (it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid)).first;
	}

	return it->second->process(fid, i);
}

int streams::flush_metrics(double now, writer &w) {
	for(auto& [sid, stream] : m_streams) {
		stream->flush_metrics(now, w);
	}

	return 0;
}

int streams::flush_list(double now, writer &w) {
	for(auto& [sid, stream] : m_streams) {
		stream->flush_list(now, w);
	}

	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);

	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);
	tsv::to_number(row[c.i.rtp.ssrc],       i.ssrc);
	tsv::to_number(row[c.i.rtp.p_type],     i.p_type);
	tsv::to_number(row[c.i.rtp.seq],        i.seq);
	tsv::to_number(row[c.i.rtp.timestamp],  i.timestamp);

	return 0;
}

void streams::resolve_ids(const info &i, stream_id &sid, flow_id &fid) const {
	const std::uint16_t dst_port = i.dst.port;
	const std::array<std::pair<std::uint16_t, flow_role>, 3> candidates = {{
		{4, flow_role::fec_col},
		{2, flow_role::fec_row},
		{0, flow_role::main},
	}};

	for(const auto &[offset, role] : candidates) {
		if(dst_port < offset) {
			continue;
		}

		const std::uint16_t base_port = static_cast<std::uint16_t>(dst_port - offset);
		stream_id candidate = make_stream_id(i.dst.addr, base_port);
		if(role == flow_role::main || m_streams.find(candidate) != m_streams.end()) {
			sid = candidate;
			fid = make_flow_id(role,
			                   i.src.addr, i.src.port,
			                   i.dst.addr, i.dst.port,
			                   i.ssrc,
			                   i.p_type);
			return;
		}
	}

	sid = make_stream_id(i.dst.addr, i.dst.port);
	fid = make_flow_id(flow_role::unknown,
	                   i.src.addr, i.src.port,
	                   i.dst.addr, i.dst.port,
	                   i.ssrc,
	                   i.p_type);
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

