#include "stream_rtp.h"

#include <array>
#include <iostream>

#include "json.h"
#include "trace.h"
#include "tsv_util.h"

namespace rtp {

flow::flow(const flow_id fid)
	: m_fid(std::move(fid))
	, m_role_text(to_string(m_fid.role))
	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst)) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		m_metrics.seq_stats.update(ex.ext_seq);
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	return json{
		{"role", m_role_text},
		{"ssrc", m_fid.ssrc},
		{"payload_type", m_fid.payload_type},
		{"endpoint", {
			{"src", m_src_text},
			{"dst", m_dst_text},
		}},
		{"last_seen", last_seen()},
	};
}

int flow::flush_metrics(double now, writer &w) {
	flow_metrics &m = m_metrics;

    json j{
		{"time", now},
	    {"proto", "RTP"},
	    {"role", m_role_text},
	    {"ssrc", m_fid.ssrc},
	    {"payload_type", m_fid.payload_type},
	    {"endpoint",{
			    {"src",  m_src_text },
			    {"dst",  m_dst_text },
		    }},
		{"bitrate", {
			{"bps", m.bitrate.value()},
			{"count", m.bitrate.stats().count},
			{"min", m.bitrate.stats().min},
			{"max", m.bitrate.stats().max},
			{"avg", m.bitrate.stats().avg()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
