struct info {
	std::string proto;
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
	uint8_t ip_proto;
	uint8_t ipv6_nxt;
};

struct stream_id {
    std::string proto;
    std::uint8_t ip_proto{0};
    ip_endpoint endpoint_a;
    ip_endpoint endpoint_b;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::string>{}(v.proto));
        hash_combine(h, std::hash<std::uint8_t>{}(v.ip_proto));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_a));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_b));
        return h;
    }
};

struct flow_id {
    std::uint8_t ip_proto{0};
    ip_endpoint src;
    ip_endpoint dst;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint8_t>{}(v.ip_proto));
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        return h;
    }
};

inline stream_id make_stream_id(
    std::string_view proto_sv,
    std::uint8_t ip_proto,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    auto ep = normalize_endpoints(src_ip, src_port, dst_ip, dst_port);
    return stream_id{
        .proto      = std::string(proto_sv),
        .ip_proto   = ip_proto,
        .endpoint_a = std::move(ep.a),
        .endpoint_b = std::move(ep.b)
    };
}

inline flow_id make_flow_id(
    std::uint8_t ip_proto,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    return flow_id{
        .ip_proto = ip_proto,
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port}
    };
}

class flow
	: public expirable {
public:
	flow(const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);

private:
	flow_id m_fid;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	int append_metrics(double now, json::array_t &out);
	int append_list(double now, json::array_t &out);

	void expire_flows(double now);
	bool empty() const noexcept { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::string m_endpoint_a_text;
	std::string m_endpoint_b_text;
	metrics::bitrate m_bitrate;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

struct pending_stream {
    double first_seen = 0.0;
    double last_seen  = 0.0;
    uint64_t packets  = 0;
    uint64_t bytes    = 0;

    void add(const info& i) {
        if (packets == 0) {
            first_seen = i.time_epoch;
        }
        last_seen = i.time_epoch;
        ++packets;
        bytes += i.frame_len;
    }
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int append_metrics(double now, json::array_t &out) override;
	int append_list(double now, json::array_t &out) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;
	std::unordered_map<stream_id, pending_stream, stream_id_hash> m_pending;

	uint64_t m_other_oneshot_flows   = 0;
	uint64_t m_other_oneshot_packets = 0;
	uint64_t m_other_oneshot_bytes   = 0;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_pending(double now);
	void expire_streams(double now);
};

static constexpr double k_pending_timeout_sec = 5.0;
static constexpr double k_flow_idle_timeout_sec = 10.0;
static constexpr double k_stream_idle_timeout_sec = 30.0;

} // namespace other

#endif /* STREAM_OTHER */
