enum class flow_role : std::uint8_t {
    main,
    fec_row,
    fec_col,
    unknown,
};

inline const char* to_string(flow_role role) noexcept {
    switch(role) {
    case flow_role::main: return "main";
    case flow_role::fec_row: return "fec_row";
    case flow_role::fec_col: return "fec_col";
    default: return "unknown";
    }
}

struct stream_id {
    ip_endpoint session_dst;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id &v) const noexcept {
        return ip_endpoint_hash{}(v.session_dst);
    }
};

struct flow_id {
    flow_role role{flow_role::unknown};
    ip_endpoint src;
    ip_endpoint dst;
    std::uint32_t ssrc{0};
    std::uint8_t payload_type{0};

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint8_t>{}(static_cast<std::uint8_t>(v.role)));
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        hash_combine(h, std::hash<std::uint32_t>{}(v.ssrc));
        hash_combine(h, std::hash<std::uint8_t>{}(v.payload_type));
        return h;
    }
};

inline stream_id make_stream_id(
    const ip_addr& dst_ip,
    std::uint16_t base_port
) {
    return stream_id{
        .session_dst = {dst_ip, base_port}
    };
}

inline flow_id make_flow_id(
    flow_role role,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port,
    std::uint32_t ssrc,
    std::uint8_t payload_type
) {
    return flow_id{
        .role = role,
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port},
        .ssrc = ssrc,
        .payload_type = payload_type,
    };
}

