int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_counts.update(i.iscontrol "'!= 0, i.msg_rexmit != 0);

	if(i.iscontrol != 0) {
		m_metrics.control_types.update(i.type);
		if(i.type == 0x0003) {
			m_metrics.nak_seq_stats.add(static_cast<double>(i.nak_seqno));
		}
	}
	else {
		m_metrics.seq_stats.update(i.seqno);
	}

	if(i.rtt > 0) {
		m_metrics.rtt.update(static_cast<double>(i.rtt));
	}
	if(i.rttvar > 0) {
		m_metrics.rttvar.update(static_cast<double>(i.rttvar));
	}
	if(i.rate > 0) {
		m_metrics.rate.update(static_cast<double>(i.rate));
	}
	if(i.rcvrate > 0) {
		m_metrics.rcvrate.update(static_cast<double>(i.rcvrate));
	}
	if(i.bw > 0) {
		m_metrics.bw.update(static_cast<double>(i.bw));
	}

	return 0;
}

