int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid)).first;
	}

	return it->second->process(i);
}

flow_id stream::resolve_flow_id(const info &i) const {
	const std::uint16_t offset = static_cast<std::uint16_t>(i.dst.port - m_sid.session_dst.port);
	flow_role role = flow_role::unknown;

	switch(offset) {
	case 0: role = flow_role::main; break;
	case 2: role = flow_role::fec_row; break;
	case 4: role = flow_role::fec_col; break;
	default: role = flow_role::unknown; break;
	}

	return make_flow_id(role,
	                   i.src.addr, i.src.port,
	                   i.dst.addr, i.dst.port,
	                   i.ssrc,
	                   i.p_type);
}

int stream::append_metrics(double now, json::array_t &out) {
	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}

	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json flows = json::array();
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}

	out.push_back(json{
		{\"proto\", \"RTP\"},
		{\"stream\", {
			{\"stream_key\", m_stream_key},
			{\"session_dst\", m_session_dst_text},
			{\"last_seen\", last_seen()},
			{\"flow_count\", m_flows.size()},
			{\"flows\", std::move(flows)},
		}},
	});

	return 0;
}

void stream::expire_flows(double now) {
    for(auto it = m_flows.begin(); it "'!= m_flows.end(); ) {
        if (it->second->expired(now, k_flow_idle_timeout_sec)) {
            it = m_flows.erase(it);
        }
        else {
            ++it;
        }
    }
}

streams::streams() {
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}

	expire_streams(i.time_epoch);

	stream_id sid = resolve_stream_id(i);

	auto it = m_streams.find(sid);
	if (it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid)).first;
	}

	return it->second->process(i);
}

int streams::append_metrics(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_metrics(now, out);
	}

	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_list(now, out);
	}

	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);

	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);
	tsv::to_number(row[c.i.rtp.ssrc],       i.ssrc);
	tsv::to_number(row[c.i.rtp.p_type],     i.p_type);
	tsv::to_number(row[c.i.rtp.seq],        i.seq);
	tsv::to_number(row[c.i.rtp.timestamp],  i.timestamp);

	return 0;
}

stream_id streams::resolve_stream_id(const info &i) const {
	const std::uint16_t dst_port = i.dst.port;
	const std::array<std::uint16_t, 3> offsets = {{4, 2, 0}};

	for(const auto offset : offsets) {
		if(dst_port < offset) {
			continue;
		}

		const std::uint16_t base_port = static_cast<std::uint16_t>(dst_port - offset);
		stream_id candidate = make_stream_id(i.dst.addr, base_port);
		if(offset == 0 || m_streams.find(candidate) != m_streams.end()) {
			return candidate;
		}
	}

	return make_stream_id(i.dst.addr, i.dst.port);
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

