int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);

	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);
	tsv::to_number(row[c.i.rtp.ssrc],       i.ssrc);
	tsv::to_number(row[c.i.rtp.p_type],     i.p_type);
	tsv::to_number(row[c.i.rtp.seq],        i.seq);
	tsv::to_number(row[c.i.rtp.timestamp],  i.timestamp);

	return 0;
}

stream_id streams::resolve_stream_id(const info &i) const {
	const std::uint16_t dst_port = i.dst.port;
	const std::array<std::uint16_t, 3> offsets = {{4, 2, 0}};

	for(const auto offset : offsets) {
		if(dst_port < offset) {
			continue;
		}

		const std::uint16_t base_port = static_cast<std::uint16_t>(dst_port - offset);
		stream_id candidate = make_stream_id(i.dst.addr, base_port);
		if(offset == 0 || m_streams.find(candidate) != m_streams.end()) {
			return candidate;
		}
	}

	return make_stream_id(i.dst.addr, i.dst.port);
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

