	const double duration_sec = seen() ? (last_seen() - m_first_seen) : 0.0;
	double window_sec = 1.0;
	if(m_metrics_window_start >= 0.0 && now > m_metrics_window_start) {
		window_sec = now - m_metrics_window_start;
	}
	const double pps = static_cast<double>(m_packet_count_window.count()) / window_sec;

	json j{
		{"time", now},
		{"proto", m_sid.proto},
		{"stream_key", m_stream_key},
		{"bitrate", {
			{"bps", m_bitrate.value()},
			{"count", m_bitrate.stats().count},
			{"min", m_bitrate.stats().min},
			{"max", m_bitrate.stats().max},
			{"avg", m_bitrate.stats().avg()},
		}},
		{"packet_rate", {
			{"pps", pps},
			{"count", m_packet_count_window.count()},
			{"seconds", window_sec},
		}},
		{"packet_count", {
			{"total", m_packet_count_total.count()},
			{"window", m_packet_count_window.count()},
		}},
		{"duration", {
			{"seconds", duration_sec},
			{"first_seen", m_first_seen},
			{"last_seen", last_seen()},
		}},
	};

	m_bitrate.clear_stats();
	m_packet_count_window.reset();
	m_metrics_window_start = now;
	out.push_back(std::move(j));
	return 0;
