		it = m_flows.emplace(fid, std::make_unique<flow>(fid)).first;
	}

	return it->second->process(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	const double duration_sec = seen() ? (last_seen() - m_first_seen) : 0.0;

	json j{
		{"time", now},
		{"proto", m_sid.proto},
		{"stream_key", m_stream_key},
		{"bitrate", {
			{"bps", m_bitrate.value()},
			{"count", m_bitrate.stats().count},
			{"min", m_bitrate.stats().min},
			{"max", m_bitrate.stats().max},
			{"avg", m_bitrate.stats().avg()},
		}},
		{"packet_rate", {
			{"pps", m_packet_rate.value()},
			{"count", m_packet_rate.stats().count},
			{"min", m_packet_rate.stats().min},
			{"max", m_packet_rate.stats().max},
			{"avg", m_packet_rate.stats().avg()},
		}},
		{"packet_count", {
			{"total", m_packet_count_total.count()},
		}},
		{"duration", {
			{"seconds", duration_sec},
			{"first_seen", m_first_seen},
			{"last_seen", last_seen()},
		}},
	};

	m_bitrate.clear_stats();
	m_packet_rate.clear_stats();
	out.push_back(std::move(j));
	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	(void)now;
	out.push_back(json{
		{"proto", m_sid.proto},
		{"stream", {
			{"stream_key", m_stream_key},
			{"endpoint", {
				{"a", m_endpoint_a_text},
				{"b", m_endpoint_b_text},
			}},
		}},
	});
	return 0;
}

void stream::expire_flows(double now) {
	for(auto it = m_flows.begin(); it != m_flows.end(); ) {
		if(it->second->expired(now, k_flow_idle_timeout_sec)) {
			it = m_flows.erase(it);
		}
		else {
			++it;
		}
	}
}

streams::streams() {
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}

    expire_pending(i.time_epoch);
    expire_streams(i.time_epoch);

    stream_id sid = make_stream_id(i.proto,
                                   i.ip_proto,
                                   i.src.addr, i.src.port,
                                   i.dst.addr, i.dst.port);

    auto it = m_streams.find(sid);
    if(it != m_streams.end()) {
        return it->second->process(i);
    }

    auto pit = m_pending.find(sid);
    if(pit != m_pending.end()) {
        auto s = std::make_unique<stream>(sid);
        int rc = s->process(i);

        m_streams.emplace(sid, std::move(s));
        m_pending.erase(pit);
        return rc;
    }

    pending_stream ps;
    ps.add(i);
    m_pending.emplace(sid, std::move(ps));

    return 0;
}

int streams::append_metrics(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_metrics(now, out);
	}
	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_list(now, out);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_string(row[c.i.com.proto], i.proto);
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);
	tsv::to_number(i.src.addr.is_v6 ?
	               row[c.i.com.ipv6_nxt] : row[c.i.com.ip_proto], i.ip_proto);
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);

	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

void streams::expire_pending(double now) {
    for(auto it = m_pending.begin(); it != m_pending.end(); ) {
        if((now - it->second.last_seen) >= k_pending_timeout_sec) {
            ++m_other_oneshot_flows;
            m_other_oneshot_packets += it->second.packets;
            m_other_oneshot_bytes   += it->second.bytes;
            it = m_pending.erase(it);
        }
        else {
            ++it;
        }
    }
}

