        "|role=" + std::string(to_string(fid.role)) +
        "|ssrc=" + std::to_string(fid.ssrc) +
        "|pt=" + std::to_string(fid.payload_type) +
        "|src=" + to_string(fid.src) +
        "|dst=" + to_string(fid.dst);
}

