flow::flow(const stream_id& sid, const flow_id fid)
	: m_fid(std::move(fid))
	, m_stream_key(make_stream_key(sid))
	, m_flow_key(make_flow_key(sid, m_fid))
	, m_role_text(to_string(m_fid.role))
	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst)) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		m_metrics.seq_stats.update(ex.ext_seq);
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	return json{
		{"flow_key", m_flow_key},
		{"role", m_role_text},
		{"ssrc", m_fid.ssrc},
		{"payload_type", m_fid.payload_type},
		{"endpoint", {
			{"src", m_src_text},
			{"dst", m_dst_text},
		}},
		{"last_seen", last_seen()},
	};
}

int flow::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;

    json j{
		{"time", now},
	    {"proto", "RTP"},
	    {"stream_key", m_stream_key},
	    {"flow_key", m_flow_key},
	    {"role", m_role_text},
	    {"ssrc", m_fid.ssrc},
	    {"payload_type", m_fid.payload_type},
	    {"endpoint",{
		    {"src",  m_src_text },
		    {"dst",  m_dst_text },
	    }},
		{"bitrate", {
			{"bps", m.bitrate.value()},
			{"count", m.bitrate.stats().count},
			{"min", m.bitrate.stats().min},
			{"max", m.bitrate.stats().max},
			{"avg", m.bitrate.stats().avg()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", m.seq_stats.gap_count().count()},
	        {"dup", m.seq_stats.dup_count().count()},
	        {"reorder", m.seq_stats.reorder_count().count()},
        }}
    };

    m.bitrate.clear_stats();
    m.interval.clear_stats();
    m.seq_stats.reset_stats();
	out.push_back(std::move(j));

	return 0;
}

stream::stream(const stream_id sid)
	: m_sid(std::move(sid))
	, m_stream_key(make_stream_key(m_sid))
	, m_session_dst_text(to_string(m_sid.session_dst)) {
}

int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid)).first;
	}

	return it->second->process(i);
}

flow_id stream::resolve_flow_id(const info &i) const {
	const std::uint16_t offset = static_cast<std::uint16_t>(i.dst.port - m_sid.session_dst.port);
	flow_role role = flow_role::unknown;

	switch(offset) {
	case 0: role = flow_role::main; break;
	case 2: role = flow_role::fec_row; break;
	case 4: role = flow_role::fec_col; break;
	default: role = flow_role::unknown; break;
	}

	return make_flow_id(role,
	                   i.src.addr, i.src.port,
	                   i.dst.addr, i.dst.port,
	                   i.ssrc,
	                   i.p_type);
}

int stream::append_metrics(double now, json::array_t &out) {
	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}

	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json flows = json::array();
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}

	out.push_back(json{
		{"proto", "RTP"},
		{"stream", {
			{"stream_key", m_stream_key},
			{"session_dst", m_session_dst_text},
			{"last_seen", last_seen()},
			{"flow_count", m_flows.size()},
			{"flows", std::move(flows)},
		}},
	});

	return 0;
}

