    };
}

inline std::string make_stream_key(const stream_id& sid) {
    return "SRT|a=" + to_string(sid.endpoint_a) +
        "|b=" + to_string(sid.endpoint_b) +
        "|streamid=" + sid.streamid;
}

inline std::string make_flow_key(const stream_id& sid, const flow_id& fid) {
    return make_stream_key(sid) +
        "|src=" + to_string(fid.src) +
        "|dst=" + to_string(fid.dst);
}

struct flow_metrics {
	metrics::bitrate bitrate;
	metrics::interval interval;
	metrics::sequence_stats seq_stats;
	metrics::value_stats nak_seq_stats;
	metrics::srt::packet_counters packet_counts;
	metrics::srt::control_packet_type_counter control_types;
	metrics::gauge rtt;
	metrics::gauge rttvar;
	metrics::gauge rate;
	metrics::gauge rcvrate;
	metrics::gauge bw;
};

class flow
	: public expirable {
public:
	flow(const stream_id& sid, const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);
	int append_metrics(double now, json::array_t &out);
	json to_list_json(double now) const;

private:
	flow_id m_fid;
	std::string m_stream_key;
	std::string m_flow_key;
	std::string m_src_text;
	std::string m_dst_text;
	flow_metrics m_metrics;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	int append_metrics(double now, json::array_t &out);
	int append_list(double now, json::array_t &out);
	void expire_flows(double now);
	bool empty() { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::string m_stream_key;
	std::string m_endpoint_a_text;
	std::string m_endpoint_b_text;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int append_metrics(double now, json::array_t &out) override;
	int append_list(double now, json::array_t &out) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_streams(double now);
};

