     47:
     48: │   │   if(proto == "SRT") {
     49: │   │   │   m_srt->process(tc, row);
     50: │   │   }
     51: │   │   else if((proto == "MPEG TS") || (proto == "RTP")) {
     52: │   │   │   m_rtp->process(tc, row);
     53: │   │   }
     54: │   │   else if(proto == "HTTP") {
     55: │   │   │   m_hls->process(tc, row);
