```cpp
std::unordered_map<std::string_view, streams*> dispatcher = {
    { "SRT",     m_srt.get() },
    { "MPEG TS", m_rtp.get() },
    { "RTP",     m_rtp.get() },
    { "HTTP",    m_hls.get() },
};
