stream::stream(const stream_id sid)
	: m_sid(std::move(sid))
	, m_stream_key(make_stream_key(m_sid))
	, m_endpoint_a_text(to_string(m_sid.endpoint_a))
	, m_endpoint_b_text(to_string(m_sid.endpoint_b)) {
}

int stream::process(const info &i) {
	m_lifetime.update(i.time_epoch);

	touch(i.time_epoch);
	m_bitrate.update(i.time_epoch, i.frame_len);
	m_packet_rate.update(i.time_epoch);
	m_packet_count_total.inc();

	flow_id fid = make_flow_id(i.ip_proto,
	                           i.src.addr, i.src.port,
	                           i.dst.addr, i.dst.port);

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(fid)).first;
	}

	return it->second->process(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	const double duration_sec = m_lifetime.duration_sec();

	json j{
		{"time", now},
