namespace metrics {

class counter {
public:
    struct result {
        std::uint64_t count{0};
    };

public:
    void reset() {
        count_ = 0;
    }

    void inc() {
        ++count_;
    }

    void add(std::uint64_t n) {
        count_ += n;
    }

    void add(bool cond) {
        if (cond) {
            ++count_;
        }
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    result value() const {
        return result{ .count = count_ };
    }

private:
    std::uint64_t count_{0};
};

struct value_stats {
    std::uint64_t count{0};
    double sum{0.0};
    double min{0.0};
    double max{0.0};

    // 分散計算用
    double mean{0.0};
    double m2{0.0};

    void clear() {
        count = 0;
        sum = 0.0;
        min = 0.0;
        max = 0.0;
        mean = 0.0;
        m2 = 0.0;
    }

    void add(double v) {
        if (count == 0) {
            min = max = v;
        } else {
            if (v < min) min = v;
            if (v > max) max = v;
        }

        sum += v;
        ++count;

        const double delta = v - mean;
        mean += delta / static_cast<double>(count);
        const double delta2 = v - mean;
        m2 += delta * delta2;
    }

    bool empty() const {
        return count == 0;
    }

    double avg() const {
        return count ? mean : 0.0;
    }

    // 母分散
    double variance() const {
        return count ? (m2 / static_cast<double>(count)) : 0.0;
    }

    // 母標準偏差
    double stddev() const {
        return std::sqrt(variance());
    }

    // 不偏分散
    double sample_variance() const {
        return (count > 1) ? (m2 / static_cast<double>(count - 1)) : 0.0;
    }

    // 不偏標準偏差
    double sample_stddev() const {
        return std::sqrt(sample_variance());
    }
};

class gauge {
public:
    void reset() {
        has_value_ = false;
        last_value_ = 0.0;
        stats_.clear();
