namespace tsv {

// using row_t = std::vector<std::string_view>;
// using field_map_t = std::unordered_map<std::string, std::size_t>;

inline void split(std::string_view line, row_t &fields) {
    fields.clear();

    const char *data = line.data();
    const size_t n = line.size();
    size_t start = 0;

    for(size_t i = 0; i < n; ++i) {
        if(data[i] == '\t') {
            fields.emplace_back(data + start, i - start);
            start = i + 1;
        }
    }

    fields.emplace_back(data + start, n - start);
}

inline field_map_t make_field_map(const std::string &header_line) {
	field_map_t map;

	std::stringstream ss(header_line);
	std::string field;
	int index = 0;

	while(std::getline(ss, field, '\t')) {
		map[field] = index++;
	}

	return map;
}

inline const std::string_view* get_field(const row_t &row, std::size_t idx) {
    if (idx >= row.size()) return nullptr;
    return &row[idx];
}

inline const std::string_view* get_field(
    const row_t& row,
    const field_map_t& fmap,
    std::string_view name)
{
    auto it = fmap.find(std::string(name));
    if (it == fmap.end()) return nullptr;
    return get_field(row, it->second);
}

