#ifndef STREAM_RTP_H
#define STREAM_RTP_H

#include <cmath>
#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>

#include "endpoint.h"
#include "json.h"
#include "metrics_common.h"
#include "metrics_rtp.h"
#include "streams.h"
#include "tsv.h"

namespace rtp {

struct info {
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
	uint32_t ssrc;
	uint8_t  p_type;
	uint16_t seq;
	uint32_t timestamp;
};

enum class flow_role : std::uint8_t {
    media,
    fec_row,
    fec_col,
    unknown,
};

inline const char* to_string(flow_role role) noexcept {
    switch(role) {
    case flow_role::media: return "media";
    case flow_role::fec_row: return "fec_row";
    case flow_role::fec_col: return "fec_col";
    default: return "unknown";
    }
}

struct stream_id {
    ip_endpoint session_dst;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id &v) const noexcept {
        return ip_endpoint_hash{}(v.session_dst);
    }
};

struct flow_id {
    flow_role role{flow_role::unknown};
    ip_endpoint src;
    ip_endpoint dst;
    std::uint32_t ssrc{0};
    std::uint8_t payload_type{0};

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint8_t>{}(static_cast<std::uint8_t>(v.role)));
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        hash_combine(h, std::hash<std::uint32_t>{}(v.ssrc));
        hash_combine(h, std::hash<std::uint8_t>{}(v.payload_type));
        return h;
    }
};

inline stream_id make_stream_id(
    const ip_addr& dst_ip,
    std::uint16_t base_port
) {
    return stream_id{
        .session_dst = {dst_ip, base_port}
    };
}

inline flow_id make_flow_id(
    flow_role role,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port,
    std::uint32_t ssrc,
    std::uint8_t payload_type
) {
    return flow_id{
        .role = role,
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port},
        .ssrc = ssrc,
        .payload_type = payload_type,
    };
}

inline std::string make_stream_key(const stream_id& sid) {
    return "RTP|session_dst=" + to_string(sid.session_dst);
}

inline std::string make_flow_key(const stream_id& sid, const flow_id& fid) {
    return make_stream_key(sid) +
        "|role=" + std::string(to_string(fid.role)) +
        "|ssrc=" + std::to_string(fid.ssrc) +
        "|pt=" + std::to_string(fid.payload_type) +
        "|src=" + to_string(fid.src) +
        "|dst=" + to_string(fid.dst);
}

struct flow_metrics {
	metrics::bitrate bitrate;
	metrics::packet_rate packet_rate;
	metrics::counter packet_count;
	metrics::interval interval;
	metrics::sequence_stats seq_stats;
	metrics::rtp::jitter jitter;
    metrics::rtp::clock_skew skew;
    metrics::rtp::seq_extender seq_ext;
    metrics::rtp::timestamp_extender ts_ext;
};

class flow
	: public expirable {
public:
	flow(const stream_id& sid, const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);
	int append_metrics(double now, json::array_t &out);
	json to_list_json(double now) const;

private:
	flow_id m_fid;
	std::string m_stream_key;
	std::string m_flow_key;
	std::string m_role_text;
	std::string m_src_text;
	std::string m_dst_text;
	flow_metrics m_metrics;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	int append_metrics(double now, json::array_t &out);
	int append_list(double now, json::array_t &out);
	void expire_flows(double now);
	bool empty() { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::string m_stream_key;
	std::string m_session_dst_text;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;

	flow_id resolve_flow_id(const info &i) const;
};

class streams
	: public ::streams {
public:
	streams();
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int append_metrics(double now, json::array_t &out) override;
	int append_list(double now, json::array_t &out) override;

private:
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_streams(double now);
	stream_id resolve_stream_id(const info &i) const;
};

