---HLS---
#ifndef STREAM_HLS_H
#define STREAM_HLS_H

#include <cstdint>
#include <string>
#include <memory>
#include <unordered_map>

#include "endpoint.h"
#include "streams.h"
#include "tsv.h"

namespace hls {

struct timeout_config {
    double flow_idle_sec{10.0};
    double stream_idle_sec{30.0};
};

struct config {
    timeout_config timeout;
};

struct info {
	uint32_t interface_id;
	ip_endpoint src;
	ip_endpoint dst;
	double   time_epoch;
	uint32_t frame_len;
};

struct stream_id {
    std::string playlist_url;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        return std::hash<std::string>{}(v.playlist_url);
    }
};

struct flow_id {
    std::string method;
    std::string host;
    std::uint16_t port{0};
    std::string path;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::string>{}(v.method));
        hash_combine(h, std::hash<std::string>{}(v.host));
        hash_combine(h, std::hash<std::uint16_t>{}(v.port));
        hash_combine(h, std::hash<std::string>{}(v.path));
        return h;
    }
};

inline stream_id make_stream_id(std::string_view playlist_url_sv) {
    return stream_id{
        .playlist_url = std::string(playlist_url_sv)
    };
}

inline flow_id make_flow_id(
    std::string_view method_sv,
    std::string_view host_sv,
    std::uint16_t port,
    std::string_view path_sv
) {
    return flow_id{
        .method = std::string(method_sv),
        .host   = std::string(host_sv),
        .port   = port,
        .path   = std::string(path_sv)
    };
}

class flow
	: public expirable {
public:
	flow(const flow_id fid);
	virtual ~flow() = default;

	int process(const info &i);

private:
	flow_id m_fid;
};

class stream
	: public expirable {
public:
	stream(const stream_id sid);
	virtual ~stream() = default;

	int process(const info &i);
	void expire_flows(double now, double flow_idle_sec);
	bool empty() { return m_flows.empty(); }

private:
	stream_id m_sid;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
};

class streams
	: public ::streams {
public:
	explicit streams(config cfg = {});
	virtual ~streams() = default;

	int process(tsv::ctx &c, const tsv::row_t &row) override;
	int append_metrics(double now, json::array_t &out) override;
	int append_list(double now, json::array_t &out) override;

private:
	config m_cfg;
	std::unordered_map<stream_id, std::unique_ptr<stream>, stream_id_hash> m_streams;

	int parse_row(tsv::ctx &c, const tsv::row_t &row, info &i);
	void expire_streams(double now);
};


} // namespace hls

#endif /* STREAM_HLS */

