#include <cstdint>
#include <cstdio>
#include <functional>

class stream;

class event {
public:
	event(stream *ctx, uint64_t retention_ms, bool enable = true, bool mask = false);
	virtual ~event();

	int clear();
	virtual bool occur(uint64_t ts);
	virtual bool recover(uint64_t ts);
	virtual int update(uint64_t ts);
	virtual int remove(uint64_t ts);
	virtual void set_enable(bool en) { m_enable = en; }
	virtual uint64_t occured_total() { return m_occured_total; }
	virtual uint64_t fired_total() { return m_fired_total; }
	virtual uint64_t occured_total_diff();
	virtual uint64_t fired_total_diff();
	virtual int notify(uint64_t ts, bool mask) = 0;
	virtual bool stat() { return (m_enable && !m_mask) ? (m_occur > m_recover) : false; }

protected:
	stream *m_ctx = 0;
	bool m_enable = false;
	bool m_mask = false;
	uint64_t m_occur = 0;
	uint64_t m_recover = 0;
	uint64_t m_occured_total = 0;
