	uint64_t m_occured_total_last = 0;
	uint64_t m_fired_total_last = 0;
	uint64_t m_retention_ns = 0;
	uint64_t m_time_prev = 0;
	uint64_t m_id = 0;
	uint64_t m_seq = 0;
};

#endif /* EVENT_H */
