/* -*- coding: utf-8 -*- */

#include "event.h"

#include <cstdint>
#include <cstdio>
#include <functional>

#include "stream.h"

//--------------------------------------------------------------------------------
event::event(stream *ctx, uint64_t retention_ms, bool enable /* = true */, bool mask /* = false */) {
	m_ctx = ctx;

	m_retention_ns = retention_ms * 1000000;
	m_enable = enable;
	m_mask   = mask;

	// m_occured_total      = 0;
	// m_fired_total        = 0;
	// m_occured_total_last = 0;
	// m_fired_total_last   = 0;
	// m_id = 0;

	clear();
}

//--------------------------------------------------------------------------------
event::~event() {
}

//--------------------------------------------------------------------------------
int event::clear() {
	m_occur = 0;
	m_recover = 0;
	m_time_prev = 0;

	return 0;
}

//--------------------------------------------------------------------------------
bool event::occur(uint64_t ts) {
	int prev_occur = m_occur;
	m_occur++;
	m_occured_total++;

	if(m_enable && (prev_occur == 0)) {
		m_fired_total++;
		notify(ts, m_mask);
	}

	return true;
}

//--------------------------------------------------------------------------------
bool event::recover(uint64_t ts) {
	if((m_occur <= 0) || (m_recover >= m_occur)) {
		return false;
	}

	m_recover = m_occur;
	m_time_prev = ts;

	return true;
}

//--------------------------------------------------------------------------------
int event::update(uint64_t ts) {
	if(m_time_prev == 0) {
		return 0;
	}

	if(m_occur > m_recover) {
		return 0;
	}

	if(ts != UINT64_MAX) {
		uint64_t lapsed_ns = ts - m_time_prev;
		if(lapsed_ns < m_retention_ns) {
			return 0;
		}
	}

	if(m_enable) {
		notify(ts, m_mask);
	}
	clear();

	return 0;
}

//--------------------------------------------------------------------------------
int event::remove(uint64_t ts) {
	recover(ts);
	update(UINT64_MAX);

	return 0;
}

//--------------------------------------------------------------------------------
uint64_t event::occured_total_diff() {
	uint64_t diff = m_occured_total - m_occured_total_last;
	m_occured_total_last = m_occured_total;

	return (m_enable && !m_mask) ? diff : 0;
}

//--------------------------------------------------------------------------------
uint64_t event::fired_total_diff() {
	uint64_t diff = m_fired_total - m_fired_total_last;
	m_fired_total_last = m_fired_total;

	return (m_enable && !m_mask) ? diff : 0;
}

