    m_hls   = std::make_unique<hls::streams>(hls_cfg, m_event_sink.get());
    m_other = std::make_unique<other::streams>(other_cfg, m_event_sink.get());

    std::unordered_map<std::string_view, streams*> dispatcher = {
	    { "SRT",  m_srt.get() },
	    { "RTP",  m_rtp.get() },
	    { "HTTP", m_hls.get() },
    };

    m_writer = std::make_unique<writer>("STM", "metrics.log");
    m_list_writer = std::make_unique<list_writer>("STM_LIST", "streams.log");

	tsv::ctx tc;
