/* -*- coding: utf-8 -*- */

#ifndef EVENT_H
#define EVENT_H

#include <cstdint>
#include <string>

#include "json.h"

class writer;

struct event_record {
	double time_epoch{0.0};
	std::string proto;
	std::string type;
	std::string stream_key;
	std::string flow_key;
	json detail{json::object()};
};

class event_sink {
public:
	explicit event_sink(writer &w);
	virtual ~event_sink() = default;

	int emit(const event_record &e);

private:
	writer &m_writer;
};

class event_state {
public:
	explicit event_state(double recovery_retention_sec = 0.0,
	                     bool enable = true,
	                     bool mask = false);
	virtual ~event_state() = default;

	void clear();
	bool occur(double now);
	bool recover(double now);
	bool update(double now);
	bool remove(double now);

	void set_enable(bool enable) { m_enable = enable; }
	void set_mask(bool mask) { m_mask = mask; }
	bool active() const { return m_active; }
	bool pending_recovery() const { return m_recovery_pending; }
	bool stat() const { return m_enable && !m_mask && m_active; }

	std::uint64_t occurred_total() const { return m_occurred_total; }
	std::uint64_t fired_total() const { return m_fired_total; }
	std::uint64_t occurred_total_diff();
	std::uint64_t fired_total_diff();

private:
	bool output_enabled() const { return m_enable && !m_mask; }
	bool fire();

	bool m_enable{true};
	bool m_mask{false};
	bool m_active{false};
	bool m_recovery_pending{false};
	double m_recovery_retention_sec{0.0};
	double m_recovery_time{0.0};
	std::uint64_t m_occurred_total{0};
	std::uint64_t m_fired_total{0};
	std::uint64_t m_occurred_total_last{0};
	std::uint64_t m_fired_total_last{0};
};

#endif /* EVENT_H */

/* -*- coding: utf-8 -*- */

#include "event.h"

#include <utility>

#include "writer.h"

//--------------------------------------------------------------------------------
event_sink::event_sink(writer &w)
	: m_writer(w) {
}

//--------------------------------------------------------------------------------
int event_sink::emit(const event_record &e) {
	json j{
		{"time", e.time_epoch},
		{"type", e.type},
	};

	if(e.proto.empty() == false) {
		j["proto"] = e.proto;
	}
	if(e.stream_key.empty() == false) {
		j["stream_key"] = e.stream_key;
	}
	if(e.flow_key.empty() == false) {
		j["flow_key"] = e.flow_key;
	}
	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	return m_writer.dump(j);
}

//--------------------------------------------------------------------------------
event_state::event_state(double recovery_retention_sec, bool enable, bool mask)
	: m_enable(enable)
	, m_mask(mask)
	, m_recovery_retention_sec(recovery_retention_sec) {
}

//--------------------------------------------------------------------------------
void event_state::clear() {
	m_active = false;
	m_recovery_pending = false;
	m_recovery_time = 0.0;
}

//--------------------------------------------------------------------------------
bool event_state::occur(double now) {
	(void)now;
	++m_occurred_total;

	if(m_active) {
		return false;
	}

	m_active = true;
	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::recover(double now) {
	if(m_active == false) {
		return false;
	}

	m_active = false;
	m_recovery_time = now;

	if(m_recovery_retention_sec <= 0.0) {
		m_recovery_pending = false;
		return fire();
	}

	m_recovery_pending = true;
	return false;
}

//--------------------------------------------------------------------------------
bool event_state::update(double now) {
	if(m_recovery_pending == false) {
		return false;
	}
	if(m_active) {
		m_recovery_pending = false;
		return false;
	}
	if((now - m_recovery_time) < m_recovery_retention_sec) {
		return false;
	}

	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::remove(double now) {
	(void)now;
	const bool was_active = m_active || m_recovery_pending;
	clear();
	return was_active ? fire() : false;
}

//--------------------------------------------------------------------------------
std::uint64_t event_state::occurred_total_diff() {
	const std::uint64_t diff = m_occurred_total - m_occurred_total_last;
	m_occurred_total_last = m_occurred_total;
	return output_enabled() ? diff : 0;
}

//--------------------------------------------------------------------------------
std::uint64_t event_state::fired_total_diff() {
	const std::uint64_t diff = m_fired_total - m_fired_total_last;
	m_fired_total_last = m_fired_total;
	return output_enabled() ? diff : 0;
}

//--------------------------------------------------------------------------------
bool event_state::fire() {
	if(output_enabled() == false) {
		return false;
	}

	++m_fired_total;
	return true;
}

