   384	stream_id streams::resolve_stream_id(const info &i) const {
   385		const std::uint16_t dst_port = i.dst.port;
   386		const std::array<std::uint16_t, 3> offsets = {{4, 2, 0}};
   387	
   388		for(const auto offset : offsets) {
   389			if(dst_port < offset) {
   390				continue;
   391			}
   392	
   393			const std::uint16_t base_port = static_cast<std::uint16_t>(dst_port - offset);
   394			stream_id candidate = make_stream_id(i.interface_id, i.dst.addr, base_port);
   395			if(offset == 0 || m_streams.find(candidate) != m_streams.end()) {
   396				return candidate;
   397			}
   398		}
   399	
   400		return make_stream_id(i.interface_id, i.dst.addr, i.dst.port);
   401	}
