   403	void streams::expire_streams(double now) {
   404		for(auto it = m_streams.begin(); it != m_streams.end(); ) {
   405			it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
   406	
   407			if(it->second->empty() &&
   408			   it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
   409				it->second->emit_lost(now);
   410				it = m_streams.erase(it);
   411			}
   412			else {
   413				++it;
   414			}
   415		}
   416	}
