    std::string streams_file{"streams.log"};
    std::string events_file{"events.log"};

    std::filesystem::path resolve(const std::string& filename) const {
        if(dir.empty()) {
            return std::filesystem::path(filename);
        }
        return std::filesystem::path(dir) / filename;
    }
