 1	import type { EventLogItem } from "./types";
 2	
 3	type AnyRecord = Record<string, any>;
 4	
 5	export function normalizeEventLine(line: string): EventLogItem | undefined {
 6	  const raw = JSON.parse(line) as AnyRecord;
 7	  const time = Number(raw.time ?? Date.now() / 1000);
 8	  const type = String(raw.type ?? "event");
 9	  const source = raw.source ?? {};
10	  const detail = raw.detail;
11	  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
12	  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
13	  const proto = source.proto ? String(source.proto) : undefined;
14	  return {
15	    id: `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
16	    time,
17	    type,
18	    level: levelForType(type),
19	    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
20	    proto,
21	    streamKey,
22	    flowKey,
23	    targetLabel: targetLabel(proto, streamKey, flowKey, detail),
24	    message: messageForType(type),
25	    detail
26	  };
27	}
28	
29	function levelForType(type: string): EventLogItem["level"] {
30	  if (/error|failed|failure/i.test(type)) return "error";
31	  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
32	  return "info";
33	}
34	
35	function messageForType(type: string) {
36	  return type
37	    .split("_")
38	    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
39	    .join(" ");
40	}
41	
42	function targetLabel(proto?: string, streamKey?: string, flowKey?: string, detail?: AnyRecord) {
43	  const endpoint = detail?.endpoint;
44	  if (proto && endpoint?.a && endpoint?.b) return `${proto} ${endpoint.a} ↔ ${endpoint.b}`;
45	  if (flowKey) return shortKey(flowKey);
46	  if (streamKey) return shortKey(streamKey);
47	  return "System";
48	}
49	
50	function shortKey(key: string) {
51	  return key.length > 96 ? `${key.slice(0, 93)}...` : key;
52	}

