int monitor::run() {
    {
	    std::ios::sync_with_stdio(false);
	    std::cin.tie(nullptr);
    }

    srt::config srt_cfg{};
    rtp::config rtp_cfg{};
    hls::config hls_cfg{};
    other::config other_cfg{};
    netif::config netif_cfg{};
    if(m_cfg.log.dir.empty() == false) {
	    std::filesystem::create_directories(m_cfg.log.dir);
    }

    m_event_writer = std::make_unique<writer>("STM_EVENT", m_cfg.log.resolve(m_cfg.log.events_file).string());
    m_event_sink = std::make_unique<event_sink>(*m_event_writer);

    m_srt   = std::make_unique<srt::streams>(srt_cfg, *m_event_sink);
    m_rtp   = std::make_unique<rtp::streams>(rtp_cfg, *m_event_sink);
    m_hls   = std::make_unique<hls::streams>(hls_cfg, *m_event_sink);
    m_other = std::make_unique<other::streams>(other_cfg, *m_event_sink);
    m_interfaces = std::make_unique<netif::interfaces>(netif_cfg, *m_event_sink);

    std::unordered_map<std::string_view, streams*> dispatcher = {
	    { "SRT",  m_srt.get() },
	    { "RTP",  m_rtp.get() },
	    { "HTTP", m_hls.get() },
    };

    m_writer = std::make_unique<writer>("STM", m_cfg.log.resolve(m_cfg.log.metrics_file).string());
    m_list_writer = std::make_unique<list_writer>("STM_LIST", m_cfg.log.resolve(m_cfg.log.streams_file).string());

	tsv::ctx tc;
    tsv::row_t row;
    std::string line;

    if(std::getline(std::cin, line)) {
	    tsv::init_ctx(tc, line);
    }

	    while(std::getline(std::cin, line)) {
		    row.clear();
		    tsv::split(line, row);

		    std::string_view proto = row[tc.i.com.proto];
		    tsv::to_number(row[tc.i.com.time_epoch], tc.r.com.time_epoch);
		    tsv::to_number(row[tc.i.com.interface_id], tc.r.com.interface_id);
		    tsv::to_string(row[tc.i.com.interface_name], tc.r.com.interface_name);
		    m_interfaces->observe(tc.r.com.interface_id, tc.r.com.interface_name);

		    auto it = dispatcher.find(proto);
	    if(it != dispatcher.end()) {
		    it->second->process(tc, row);
	    }
	    else {
		    m_other->process(tc, row);
	    }

	    auto br = m_second_boundary.update(tc.r.com.time_epoch);
	    if(br.changed) {
		    m_interfaces->process(tc.r.com.time_epoch);
		    m_srt->update_events(tc.r.com.time_epoch);
		    m_rtp->update_events(tc.r.com.time_epoch);
		    m_hls->update_events(tc.r.com.time_epoch);
		    m_other->update_events(tc.r.com.time_epoch);
		    m_interfaces->update_events(tc.r.com.time_epoch);
		    json::array_t metrics_list;
		    m_srt->append_metrics(tc.r.com.time_epoch, metrics_list);
		    m_rtp->append_metrics(tc.r.com.time_epoch, metrics_list);
		    m_hls->append_metrics(tc.r.com.time_epoch, metrics_list);
		    m_other->append_metrics(tc.r.com.time_epoch, metrics_list);
		    json::array_t interface_metrics;
		    m_interfaces->append_metrics(tc.r.com.time_epoch, interface_metrics);

		    json metrics_root{
		        {"time", tc.r.com.time_epoch},
		        {"metrics", std::move(metrics_list)},
		        {"interfaces", std::move(interface_metrics)},
		    };
		    m_writer->dump(metrics_root);

		    json::array_t streams_list;
		    m_srt->append_list(tc.r.com.time_epoch, streams_list);
		    m_rtp->append_list(tc.r.com.time_epoch, streams_list);
		    m_hls->append_list(tc.r.com.time_epoch, streams_list);
		    m_other->append_list(tc.r.com.time_epoch, streams_list);
		    json::array_t interface_list;
		    m_interfaces->append_list(tc.r.com.time_epoch, interface_list);

		    json list_root{
		        {"time", tc.r.com.time_epoch},
		        {"streams", std::move(streams_list)},
		        {"interfaces", std::move(interface_list)},
		    };
		    m_list_writer->dump(list_root);
	    }
    }

    return 0;
}

int monitor::stop() {
	return 0;
}

