:root {
  color-scheme: dark;
  font-family: "Aptos", "Segoe UI", sans-serif;
  background: #071018;
  color: #e8eef5;
  --panel: rgba(12, 23, 34, .86);
  --panel-strong: rgba(17, 32, 47, .96);
  --line: rgba(143, 164, 188, .18);
  --muted: #8fa4bc;
  --accent: #66d9ef;
  --accent-2: #f7c873;
}

* { box-sizing: border-box; }
html, body, #root {
  overscroll-behavior-x: none;
}
body { margin: 0; min-width: 320px; background: radial-gradient(circle at 10% 0%, rgba(102,217,239,.16), transparent 30%), linear-gradient(135deg, #071018 0%, #111820 48%, #221a13 100%); }
button, input { font: inherit; }

