.hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 20px 64px rgba(0,0,0,.28); }
.eyebrow { margin: 0 0 8px; color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 0; font-size: clamp(30px, 5vw, 58px); line-height: .96; letter-spacing: -.05em; max-width: 740px; }
.summary-strip { display: grid; grid-template-columns: repeat(4, minmax(86px, 1fr)); gap: 10px; min-width: min(520px, 100%); }
.summary-card, .stat-card { border: 1px solid var(--line); border-radius: 18px; padding: 11px; background: rgba(255,255,255,.045); }
.summary-card span, .stat-card span { display: block; color: var(--muted); font-size: 12px; }
.summary-card strong, .stat-card strong { display: block; margin-top: 4px; font-size: 18px; }
.workspace { display: grid; grid-template-columns: minmax(390px, 42vw) 1fr; gap: 14px; margin-top: 14px; align-items: start; }
.list-pane, .detail-pane { border: 1px solid var(--line); border-radius: 28px; background: var(--panel); backdrop-filter: blur(18px); min-height: 580px; overflow: hidden; }
.list-toolbar { display: grid; grid-template-columns: 1fr; gap: 10px; padding: 16px; border-bottom: 1px solid var(--line); }
.list-toolbar-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; min-width: 0; }
