:root {
  color-scheme: dark;
  font-family: "Aptos", "Segoe UI", sans-serif;
  background: #071018;
  color: #e8eef5;
  --panel: rgba(12, 23, 34, .86);
  --panel-strong: rgba(17, 32, 47, .96);
  --line: rgba(143, 164, 188, .18);
  --muted: #8fa4bc;
  --accent: #66d9ef;
  --accent-2: #f7c873;
}

* { box-sizing: border-box; }
html, body, #root {
  overscroll-behavior-x: none;
}
body { margin: 0; min-width: 320px; background: radial-gradient(circle at 10% 0%, rgba(102,217,239,.16), transparent 30%), linear-gradient(135deg, #071018 0%, #111820 48%, #221a13 100%); }
button, input { font: inherit; }

.app-shell { min-height: 100vh; padding: 0; }
.app-frame { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 0; align-items: start; min-height: 100vh; }
.app-main {
  min-width: 0;
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  padding: 18px 18px 18px 16px;
  overflow: hidden;
}
.menu-rail {
  position: sticky;
  top: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 14px;
  min-height: 100vh;
  padding: 14px 10px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(102,217,239,.14), transparent 32%),
    linear-gradient(180deg, rgba(12, 23, 34, .96), rgba(17, 24, 34, .88));
  box-shadow: 0 20px 64px rgba(0,0,0,.22);
  backdrop-filter: blur(18px);
  transition: width .18s ease, padding .18s ease;
}
.menu-rail.collapsed { width: 72px; }
.menu-rail.expanded { width: 220px; }
.menu-rail-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 42px;
  padding: 0 10px;
  border: 1px solid rgba(143, 164, 188, .18);
  border-radius: 10px;
  background: rgba(255,255,255,.03);
  color: #e8eef5;
  cursor: pointer;
}
.menu-rail-toggle:hover { background: rgba(102,217,239,.08); border-color: rgba(102,217,239,.24); }
.menu-rail-toggle-icon {
  display: grid;
  place-items: center;
  width: 20px;
  color: var(--accent);
  font-size: 16px;
  line-height: 1;
}
.menu-rail-brand {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.menu-rail-nav {
  display: grid;
  gap: 8px;
  align-content: start;
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item.active {
  background: rgba(102,217,239,.08);
  border-color: rgba(102,217,239,.16);
  color: #eef4fb;
}
.menu-item-icon {
  display: grid;
  place-items: center;
  width: 20px;
  flex: 0 0 20px;
  color: var(--accent);
  font-size: 17px;
  line-height: 1;
}
.menu-item-copy strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: inherit;
}
.menu-item-copy small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}
.hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 20px 64px rgba(0,0,0,.28); }
.eyebrow { margin: 0 0 8px; color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 0; font-size: clamp(30px, 5vw, 58px); line-height: .96; letter-spacing: -.05em; max-width: 740px; }
.summary-strip { display: grid; grid-template-columns: repeat(4, minmax(86px, 1fr)); gap: 10px; min-width: min(520px, 100%); }
.summary-card, .stat-card { border: 1px solid var(--line); border-radius: 18px; padding: 11px; background: rgba(255,255,255,.045); }
.summary-card span, .stat-card span { display: block; color: var(--muted); font-size: 12px; }
.summary-card strong, .stat-card strong { display: block; margin-top: 4px; font-size: 18px; }
.workspace {
  display: grid;
  grid-template-columns: minmax(390px, 42vw) 1fr;
  gap: 14px;
  margin-top: 14px;
  align-items: start;
  min-height: 0;
  overflow: hidden;
}

.stats-section h3 { font-size: inherit; line-height: normal; margin-bottom: 8px; }
/* Keep chart DOM height stable during realtime updates */
.chart-card { position: relative; overflow-anchor: none; }
.chart-host { width: 100%; }
.chart-empty-overlay { position: absolute; left: 14px; right: 14px; bottom: 14px; pointer-events: none; }
.detail-pane { overflow-anchor: none; }
.search-box { position: relative; display: block; }
.search-box > span { position: absolute; left: 12px; top: 50%; transform: translateY(-52%); color: var(--muted); font-size: 18px; line-height: 1; pointer-events: none; }
.search-box input { padding-left: 36px; }
.search-box > span { font-size: 22px; }
.events-card { border: 1px solid var(--line); border-radius: 7px; background: var(--panel-strong); padding: 10px; margin-bottom: 14px; }
.events-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.events-header h3 { margin: 0; }
.events-tabs { display: inline-flex; gap: 4px; padding: 3px; border: 1px solid var(--line); border-radius: 6px; background: rgba(0,0,0,.18); }
.events-tabs button { border: 0; border-radius: 4px; background: transparent; color: var(--muted); padding: 5px 9px; cursor: pointer; font-size: 12px; }
.events-tabs button.active { background: rgba(102,217,239,.1); color: var(--accent); }
.events-list { max-height: 220px; overflow: auto; display: grid; gap: 4px; }
.event-row { display: grid; grid-template-columns: 72px 52px minmax(120px, .8fr) minmax(160px, 1fr); align-items: center; gap: 8px; padding: 6px 8px; border: 1px solid var(--line); border-radius: 5px; background: rgba(255,255,255,.018); font-size: 12px; }
.event-time, .event-target { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-message { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-level { text-transform: uppercase; font-size: 10px; font-weight: 800; letter-spacing: .08em; color: #8bd17c; }
.event-row.warn .event-level { color: #d6b66f; }
.event-row.error .event-level { color: #d98b7f; }
.events-empty { min-height: 96px; display: grid; place-items: center; color: var(--muted); border: 1px dashed var(--line); border-radius: 5px; }
@media (max-width: 720px) {
  .event-row { grid-template-columns: 68px 48px 1fr; }
  .event-message { grid-column: 1 / -1; }
}
/* Independent resizable events pane */
.workspace { align-items: stretch; }
.right-column { display: grid; gap: 0; min-height: 560px; max-height: calc(100vh - 98px); }
.right-column .detail-pane { min-height: 0; max-height: none; height: 100%; }
.pane-splitter { cursor: row-resize; position: relative; }
.pane-splitter::before { content: ""; position: absolute; left: 10px; right: 10px; top: 3px; height: 2px; border-radius: 99px; background: rgba(143,164,188,.26); }
.pane-splitter:hover::before { background: rgba(102,217,239,.55); }
body.is-resizing-pane {
  cursor: col-resize;
  user-select: none;
}
.resize-capture {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: transparent;
  touch-action: none;
  user-select: none;
}
.resize-capture-width {
  cursor: col-resize;
}
.resize-capture-height {
  cursor: row-resize;
}
.pane-splitter,
.workspace-splitter {
  touch-action: none;
  user-select: none;
}
.right-column .events-card { min-height: 0; height: 100%; margin-bottom: 0; overflow: hidden; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.right-column .events-list { max-height: none; min-height: 0; }
@media (max-width: 1100px) {
  .right-column { max-height: none; grid-template-rows: minmax(420px, auto) 8px 240px !important; }
}
/* Fixed-height event rows and absolute timestamp layout */
.events-list { display: flex; flex-direction: column; gap: 4px; }
.event-row { height: 30px; min-height: 30px; grid-template-columns: 132px 52px minmax(120px, .8fr) minmax(160px, 1fr); }
.event-time { font-variant-numeric: tabular-nums; }
.right-column .events-card { min-height: 240px; }
/* Fit the whole app into the viewport; scroll inside panes only */
html, body, #root { height: 100%; overflow: hidden; }
.app-shell { height: 100vh; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; padding: 10px; overflow: hidden; }
.workspace { min-height: 0; margin-top: 0; }
.list-pane, .detail-pane { min-height: 0; }
.stream-table { max-height: none; height: calc(100% - 92px); }
.right-column { min-height: 0; max-height: none; height: 100%; }
.event-row { height: 26px; min-height: 26px; padding: 4px 8px; }
.events-list { gap: 3px; }
.right-column .events-card { min-height: 220px; }
.events-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; min-width: 0; }
.event-search { position: relative; display: block; width: min(240px, 34vw); }
.event-search > span { position: absolute; left: 9px; top: 50%; transform: translateY(-52%); color: var(--muted); font-size: 17px; line-height: 1; pointer-events: none; }
.event-search input { width: 100%; border: 1px solid var(--line); background: rgba(0,0,0,.2); color: #e8eef5; border-radius: 5px; padding: 6px 9px 6px 29px; outline: none; font-size: 12px; }
.event-search input:focus { border-color: rgba(102,217,239,.42); }
@media (max-width: 720px) {
  .events-header { align-items: stretch; flex-direction: column; }
  .events-actions { justify-content: space-between; }
  .event-search { width: 100%; }
}
/* Unify pane radius and background */
.hero-panel,
.list-pane,
.detail-pane,
.events-card { border-radius: 7px; }
.events-card { background: var(--panel); }
/* Responsive fallback: stack panes and allow page scrolling on narrow widths */
@media (max-width: 1100px) {
  html, body, #root { height: auto; overflow: auto; }
  .app-shell { height: auto; min-height: 100vh; overflow: visible; }
  .workspace { grid-template-columns: 1fr; min-height: 0; }
  .stream-table { height: auto; max-height: 420px; }
  .right-column { height: auto; max-height: none; min-height: 0; grid-template-rows: auto 0 240px !important; }

