import { existsSync } from "node:fs";
import fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { TailFile } from "./ingest/tailFile";
import { normalizeInterfacesLine, normalizeMetricsLine, normalizeStreamsLine } from "./normalizer";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";

async function main() {
  ensureLogFilesExist();

  const app = fastify({ logger: true });
  const store = new StreamStore(config.historyWindowSec, config.staleAfterSec, config.maxEvents);

  await registerRoutes(app, store);

  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, {
      root: config.clientDist,
      prefix: "/"
    });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") {
        return reply.code(404).send({ error: "not found" });
      }
      return reply.sendFile("index.html");
    });
  }

  const sockets = new SocketServer(app.server, store);
  sockets.start();

  const streamsTail = new TailFile({
    path: config.streamsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        for (const item of normalizeStreamsLine(line)) store.upsertStream(item.stream);
      } catch (error) {
        app.log.warn({ error }, "failed to parse streams log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail streams log")
  });

  const metricsTail = new TailFile({
    path: config.metricsLog,
    pollMs: config.pollMs,
    onChunk: ({ start, end, bytes, lines, observedAt, processedAt, processingMs }) => {
      app.log.info({
        path: config.metricsLog,
        start,
        end,
        bytes,
        lines,
        observedAt,
        observedAtIso: new Date(observedAt).toISOString(),
        processedAt,
        processedAtIso: new Date(processedAt).toISOString(),
        processingMs
      }, "metrics log update detected");
    },
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        for (const item of normalizeMetricsLine(line)) store.addMetric(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metrics log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail metrics log")
  });


  const eventsTail = new TailFile({
    path: config.eventsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const event = normalizeEventLine(line);
        if (event) store.addEvent(event);
      } catch (error) {
        app.log.warn({ error }, "failed to parse events log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail events log")
  });

  streamsTail.start();
  metricsTail.start();
  eventsTail.start();

  const close = async () => {
    streamsTail.stop();
    metricsTail.stop();
    eventsTail.stop();
    await app.close();
  };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());

  await app.listen({ host: config.host, port: config.port });
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

import type { Server as HttpServer } from "node:http";
import { WebSocketServer, type WebSocket } from "ws";
import type { StreamStore } from "../state/store";
import type { WsMessage } from "../types";

export class SocketServer {
  private readonly wss = new WebSocketServer({ noServer: true });
  private readonly metricSubscriptions = new Map<WebSocket, string>();
  private pendingStreams = false;

  constructor(
    private readonly server: HttpServer,
    private readonly store: StreamStore
  ) {}

  start() {
    this.server.on("upgrade", (request, socket, head) => {
      if (request.url !== "/ws") return;
      this.wss.handleUpgrade(request, socket, head, (ws) => {
        this.wss.emit("connection", ws, request);
      });
    });

    this.wss.on("connection", (ws) => {
      this.send(ws, { type: "snapshot", streams: this.store.listStreams(), interfaces: this.store.listInterfaces(), summary: this.store.getSummary() });
      ws.on("message", (raw) => this.handleClientMessage(ws, raw.toString()));
      ws.on("close", () => this.metricSubscriptions.delete(ws));
    });

    this.store.on("streams:update", () => this.scheduleStreamsUpdate());
    this.store.on("metrics:update", (streamKey: string) => this.broadcastSubscribedMetrics(streamKey));

    this.store.on("events:update", (event) => {
      this.broadcast({ type: "events:update", events: [event] });
    });
  }

  private scheduleStreamsUpdate() {
    if (this.pendingStreams) return;
    this.pendingStreams = true;
    setTimeout(() => {
      this.pendingStreams = false;
      this.broadcast({ type: "streams:update", streams: this.store.listStreams(), interfaces: this.store.listInterfaces(), summary: this.store.getSummary() });
    }, 250);
  }

  private broadcast(message: WsMessage) {
    const payload = JSON.stringify(message);
    for (const client of this.wss.clients) {
      if (client.readyState === client.OPEN) client.send(payload);
    }
  }

  private broadcastSubscribedMetrics(streamKey: string) {
    const clients = [...this.wss.clients].filter((client) =>
      client.readyState === client.OPEN && this.metricSubscriptions.get(client) === streamKey
    );
    if (clients.length === 0) return;

    const metrics = this.store.getMetrics(streamKey);
    if (!metrics) return;

    const payload = JSON.stringify({ type: "stream:metrics", streamKey, metrics } satisfies WsMessage);
    for (const client of clients) client.send(payload);
  }

  private handleClientMessage(client: WebSocket, raw: string) {
    try {
      const message = JSON.parse(raw) as { type?: string; streamKey?: unknown };
      if (message.type !== "stream:subscribe") return;
      if (typeof message.streamKey === "string" && message.streamKey.length > 0) {
        this.metricSubscriptions.set(client, message.streamKey);
      } else {
        this.metricSubscriptions.delete(client);
      }
    } catch {
      // Ignore malformed client messages; the connection can continue receiving snapshots.
    }
  }

  private send(client: WebSocket, message: WsMessage) {
    if (client.readyState === client.OPEN) client.send(JSON.stringify(message));
  }
}

