    std::string command = "tshark -r " + filePath +
                          " -n -T fields -E separator=/t "
                          "-e frame.time_epoch -e ip.src -e rtp.seq -e rtp.timestamp 2>/dev/null";

    std::cout << "[INFO] Analyzing: " << filename << std::endl;

    // popenでtsharkの出力をパイプとして読み込む
    FILE* pipe = popen(command.c_str(), "r");
    if (!pipe) return;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
        // --- ここに解析ロジックを実装 ---
        // 例: タブで分割してシーケンス番号の連続性をチェック
        // processLine(buffer);
	    std::cerr << buffer << std::endl;
    }
    pclose(pipe);

    // 解析後にファイルを削除するか、アーカイブするかを選択
    // std::remove(filePath.c_str());
}

int main() {
	int fd = inotify_init();
	if (fd < 0) {
		perror("inotify_init");
		return 1;
	}

	// 書き込み終了 (IN_CLOSE_WRITE) を監視
	int wd = inotify_add_watch(fd, WATCH_DIR.c_str(), IN_CLOSE_WRITE);
	if (wd < 0) {
		perror("inotify_add_watch");
		return 1;
	}

	std::cout << "[START] Monitoring " << WATCH_DIR << "..." << std::endl;

	std::array<char, 16 * 1024> event_buf{};
	while (true) {
		ssize_t len = read(fd, event_buf.data(), event_buf.size());
		if(len < 0) {
			break;
		}

		for(ssize_t offset = 0; offset < len;) {
			auto* event = reinterpret_cast<struct inotify_event*>(event_buf.data() + offset);
			offset += sizeof(struct inotify_event) + event->len;

			if (event->len > 0) {
				std::string filename = event->name;

				// dumpcapが作成したpcapファイルのみを対象にする
				if (filename.find(PCAP_PREFIX) != std::string::npos &&
				    filename.find(".pcap") != std::string::npos) {
					analyzePcap(filename);
				}
			}
		}
	}

	inotify_rm_watch(fd, wd);
	close(fd);

	return 0;
}

