	}
	else if(pending_count < g_last_pending_count) {
		std::cout << "[BACKLOG] pending=" << pending_count
		          << " (-" << (g_last_pending_count - pending_count) << ", decreasing)"
		          << std::endl;
	}
	else {
		std::cout << "[BACKLOG] pending=" << pending_count << " (stable)" << std::endl;
	}

	g_last_pending_count = pending_count;
}

/**
 * tsharkを実行して1秒分のデータを解析する関数
 */
void analyzePcap(const std::string& filename) {
    std::string filePath = WATCH_DIR + filename;

    // tsharkコマンドの構築 (-r でファイルを読み込み)
    // -S (separator) にタブを指定し、必要なフィールドを抽出
    std::string command = "tshark -r " + filePath +
                          " -n -T fields -E separator=/t "
                          "-e frame.time_epoch -e ip.src -e rtp.seq -e rtp.timestamp 2>/dev/null";

    std::cout << "[INFO] Analyzing: " << filename << std::endl;

    // popenでtsharkの出力をパイプとして読み込む
    FILE* pipe = popen(command.c_str(), "r");
    if (!pipe) return;

    char buffer[1024];
