monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)) {
	init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	srt::config srt_cfg{};
	rtp::config rtp_cfg{};
	hls::config hls_cfg{};
	other::config other_cfg{};
	netif::config netif_cfg{};
	if(m_cfg.log.dir.empty() == false) {
		std::filesystem::create_directories(m_cfg.log.dir);
	}

	m_event_writer = std::make_unique<writer>("STM_EVENT", m_cfg.log.resolve(m_cfg.log.events_file).string());
	m_event_sink = std::make_unique<event_sink>(*m_event_writer);

	m_srt   = std::make_unique<srt::streams>(srt_cfg, *m_event_sink);
	m_rtp   = std::make_unique<rtp::streams>(rtp_cfg, *m_event_sink);
	m_hls   = std::make_unique<hls::streams>(hls_cfg, *m_event_sink);
	m_other = std::make_unique<other::streams>(other_cfg, *m_event_sink);
	m_interfaces = std::make_unique<netif::interfaces>(netif_cfg, *m_event_sink);

	// std::unordered_map<std::string_view, streams*> dispatcher = {
	m_dispatcher = { { "SRT",  m_srt.get() },
	                 { "RTP",  m_rtp.get() },
	                 { "HTTP", m_hls.get() } };

	m_writer = std::make_unique<writer>("STM", m_cfg.log.resolve(m_cfg.log.metrics_file).string());
	m_list_writer = std::make_unique<list_writer>("STM_LIST", m_cfg.log.resolve(m_cfg.log.streams_file).string());

	m_pcap_watcher = std::make_unique<pcap_watch>(pcap_watch::config{
		.watch_dir = "/tmp/capture/",
		.pcap_prefix = "cap_",
		.ring_file_count = 5,
		.backlog_trend_threshold = 5,
	});

	m_pcap_watcher->set_callback(*this, &monitor::process_pcap);

	return 0;
}

int monitor::run() {
	return m_pcap_watcher->run();
}

bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_default_read_command(file_path);

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
		return false;
	}

	if(process_tsv(pipe) != 0) {
		std::cerr << "[WARN] parse_tsv failed for " << file_path.filename().string() << std::endl;
	}

	int status = pclose(pipe);
	if(status == -1) {
		std::cerr << "[WARN] pclose failed for " << file_path.filename().string() << std::endl;
		return false;
