    return &row[idx];
}

inline const std::string_view* get_field(const row_t &row, int idx) {
    if (idx < 0) return nullptr;
    return get_field(row, static_cast<std::size_t>(idx));
}

inline std::string_view field_or_empty(const row_t &row, int idx) {
    const auto *field = get_field(row, idx);
    return field ? *field : std::string_view{};
}

inline const std::string_view* get_field(
    const row_t& row,
    const field_map_t& fmap,
    std::string_view name)
{
