import { EventEmitter } from "node:events";
import { descriptorForMetric, type NormalizedInterfaceInput, type NormalizedMetricInput } from "../normalizer";
import type {
  EventLogItem,
  FlowMetricPoint,
  FlowState,
  InterfaceListItem,
  InterfaceMetricsResponse,
  MetricDescriptor,
  MetricPoint,
  NumericStat,
  OverviewStats,
  StreamListItem,
  StreamMetricsResponse,
  StreamState,
  Summary,
  TimeSeriesMetric
} from "../types";

export class StreamStore extends EventEmitter {
  private interfaces = new Map<string, InterfaceListItem>();
  private interfaceHistory = new Map<string, FlowMetricPoint[]>();
  private streams = new Map<string, StreamState>();
  private flowHistory = new Map<string, FlowMetricPoint[]>();
  private flowSparklines = new Map<string, number[]>();
  private latestUpdate?: number;
  private events: EventLogItem[] = [];
  private eventCountsByStream = new Map<string, number>();
  private eventCountsByStreamOnly = new Map<string, number>();
  private eventCountsByFlow = new Map<string, number>();

  constructor(
    private readonly historyWindowSec: number,
    private readonly staleAfterSec: number,
    private readonly maxEvents = 1000
  ) {
    super();
  }

  upsertStream(stream: StreamState) {
    this.attachInterfaceName(stream);
    const existing = this.streams.get(stream.streamKey);
    const mergedFlows = mergeFlows(existing?.flows ?? [], stream.flows);
    const next: StreamState = {
      ...existing,
      ...stream,
      flows: mergedFlows,
      flowCount: mergedFlows.length,
      flowRoles: [...new Set(mergedFlows.map((flow) => flow.role))],
      bitrate: existing?.bitrate ?? {},
      sparkline: existing?.sparkline ?? []
    };
    this.streams.set(stream.streamKey, next);
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, stream.lastSeen);
    this.markStale();
    this.emit("streams:update");
  }

  upsertInterfaces(items: NormalizedInterfaceInput[]) {
    if (items.length === 0) return;
    for (const item of items) {
      const existing = this.interfaces.get(item.key);
      const rxSparkline = existing?.rxSparkline ?? [];
      const txSparkline = existing?.txSparkline ?? [];
      if (item.hasMetrics) {
        rxSparkline.push(item.rxBitrate.value ?? item.rxBitrate.avg ?? 0);
        txSparkline.push(item.txBitrate.value ?? item.txBitrate.avg ?? 0);
        if (rxSparkline.length > 60) rxSparkline.splice(0, rxSparkline.length - 60);
        if (txSparkline.length > 60) txSparkline.splice(0, txSparkline.length - 60);
        const history = this.interfaceHistory.get(item.key) ?? [];
        history.push({ time: item.lastSeen ?? Date.now() / 1000, metrics: interfaceMetricsForHistory(item) });
        this.prune(history, item.lastSeen ?? Date.now() / 1000);
        this.interfaceHistory.set(item.key, history);
      }
      this.interfaces.set(item.key, {
        ...existing,
        ...withoutInterfaceMarker(item),
        rx: item.hasMetrics ? item.rx : existing?.rx ?? item.rx,
        tx: item.hasMetrics ? item.tx : existing?.tx ?? item.tx,
        rxBitrate: item.hasMetrics ? item.rxBitrate : existing?.rxBitrate ?? item.rxBitrate,
        txBitrate: item.hasMetrics ? item.txBitrate : existing?.txBitrate ?? item.txBitrate,
        rxSparkline,
        txSparkline,
        streamCount: existing?.streamCount ?? 0
      });
    }
    this.refreshInterfaceNames();
    this.emit("streams:update");
  }

  addMetric(input: NormalizedMetricInput) {
    const stream = this.ensureStream(input);
    const flow = this.ensureFlow(stream, input);
    if (input.interfaceId !== undefined) {
      stream.interfaceId ??= input.interfaceId;
      flow.interfaceId ??= input.interfaceId;
      const interfaceName = this.interfaceById(input.interfaceId)?.name;
      if (interfaceName) {
        stream.interfaceName ??= interfaceName;
        flow.interfaceName ??= interfaceName;
      }
    }
    flow.metrics = input.metrics;
    flow.lastSeen = input.time;

    const history = this.flowHistory.get(input.flowKey) ?? [];
    history.push({ time: input.time, metrics: input.metrics });
    const bitrate = input.metrics.bitrate?.value ?? input.metrics.bitrate?.avg ?? 0;
    const sparkline = this.flowSparklines.get(input.flowKey) ?? [];
    sparkline.push(bitrate);
    if (sparkline.length > 60) sparkline.splice(0, sparkline.length - 60);
    this.flowSparklines.set(input.flowKey, sparkline);
    this.prune(history, input.time);
    this.flowHistory.set(input.flowKey, history);

    this.recomputeStreamBitrate(stream, input.time);
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, input.time);
    this.markStale();
    this.emit("streams:update");
    this.emit("metrics:update", input.streamKey);
  }

  listStreams(): StreamListItem[] {
    this.markStale();
    return [...this.streams.values()]
      .sort((a, b) => (b.bitrate.value ?? 0) - (a.bitrate.value ?? 0))
      .map((stream) => ({
        ...stream,
        overview: this.overviewForStream(stream),
        flows: stream.flows.map((flow) => ({
          flowKey: flow.flowKey,
          role: flow.role,
          label: flow.label,
          interfaceId: flow.interfaceId,
          interfaceName: flow.interfaceName,
          endpointSrc: flow.endpointSrc,
          endpointDst: flow.endpointDst,
          lastSeen: flow.lastSeen,
          bitrate: flow.metrics.bitrate ?? {},
          sparkline: this.flowSparklines.get(flow.flowKey) ?? [],
          overview: this.overviewForFlow(flow, stream.streamKey)
        }))
      }));
  }

  listInterfaces(): InterfaceListItem[] {
    const streamCounts = new Map<number, number>();
    for (const stream of this.streams.values()) {
      if (stream.interfaceId !== undefined) {
        streamCounts.set(stream.interfaceId, (streamCounts.get(stream.interfaceId) ?? 0) + 1);
      }
    }
    return [...this.interfaces.values()]
      .map((item) => ({ ...item, streamCount: item.interfaceId !== undefined ? streamCounts.get(item.interfaceId) ?? 0 : 0 }))
      .sort((a, b) => (a.interfaceId ?? Number.MAX_SAFE_INTEGER) - (b.interfaceId ?? Number.MAX_SAFE_INTEGER) || a.name.localeCompare(b.name));
  }

  getInterfaceMetrics(interfaceId: number, windowSec = this.historyWindowSec): InterfaceMetricsResponse | undefined {
    return this.getInterfaceMetricsByKey(`if:${interfaceId}`, windowSec);
  }

  getInterfaceMetricsByKey(key: string, windowSec = this.historyWindowSec): InterfaceMetricsResponse | undefined {
    const item = this.interfaces.get(key);
    if (!item) return undefined;

    const since = (this.latestUpdate ?? item.lastSeen ?? Date.now() / 1000) - windowSec;
    const history = (this.interfaceHistory.get(item.key) ?? []).filter((point) => point.time >= since);
    const metricKeys = new Set<string>();
    const metrics = buildMetrics(history, metricKeys);

    return {
      key: item.key,
      interfaceId: item.interfaceId,
      name: item.name,
      windowSec,
      metrics
    };
  }

  getStream(streamKey: string) {
    this.markStale();
    return this.streams.get(streamKey);
  }

  getMetrics(streamKey: string, windowSec = this.historyWindowSec): StreamMetricsResponse | undefined {
    const stream = this.streams.get(streamKey);
    if (!stream) return undefined;

    const since = (this.latestUpdate ?? Date.now() / 1000) - windowSec;
    const metricKeys = new Set<string>();
    const flows = stream.flows.map((flow) => {
      const history = (this.flowHistory.get(flow.flowKey) ?? []).filter((point) => point.time >= since);
      const metrics = buildMetrics(history, metricKeys);
      return {
        flowKey: flow.flowKey,
        role: flow.role,
        label: flow.label,
        endpointSrc: flow.endpointSrc,
        endpointDst: flow.endpointDst,
        metrics
      };
    });

    const streamBitrate = this.buildStreamBitrate(stream, since);
    metricKeys.add("bitrate");

    const descriptors = [...metricKeys]
      .map(descriptorForMetric)
      .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

    return {
      streamKey,
      windowSec,
      streamBitrate,
      flows,
      descriptors
    };
  }

  addEvent(event: EventLogItem) {
    this.events.push(event);
    this.incrementEventCounts(event, 1);
    if (this.events.length > this.maxEvents) {
      const removed = this.events.splice(0, this.events.length - this.maxEvents);
      for (const item of removed) this.incrementEventCounts(item, -1);
    }
    this.emit("events:update", event);
  }

  listEvents(options: { streamKey?: string; flowKey?: string; interfaceId?: number; limit?: number } = {}) {
    const limit = Math.max(1, Math.min(options.limit ?? 100, this.maxEvents));
    return this.events
      .filter((event) => {
        if (options.flowKey) return event.flowKey === options.flowKey || event.streamKey === options.streamKey;
        if (options.streamKey) return event.streamKey === options.streamKey;
        if (options.interfaceId !== undefined) return event.interfaceId === options.interfaceId;
        return true;
      })
      .slice(-limit)
      .reverse();
  }

  getSummary(): Summary {
    this.markStale();
    const byKind: Record<string, number> = {};
    let activeStreams = 0;
    for (const stream of this.streams.values()) {
      byKind[stream.kind] = (byKind[stream.kind] ?? 0) + 1;
      if (stream.active) activeStreams += 1;
    }
    return {
      totalStreams: this.streams.size,
      activeStreams,
      updatedAt: this.latestUpdate,
      byKind
    };
  }

  private ensureStream(input: NormalizedMetricInput): StreamState {
    const existing = this.streams.get(input.streamKey);

import type { FlowState, InterfaceListItem, MetricDescriptor, NumericStat, StreamState } from "./types";

type AnyRecord = Record<string, any>;

type NormalizedStreamInput = {
  time: number;
  stream: StreamState;
};

export type NormalizedInterfaceInput = Omit<InterfaceListItem, "streamCount"> & {
  hasMetrics: boolean;
};

export type NormalizedMetricInput = {
  time: number;
  streamKey: string;
  flowKey: string;
  role: string;
  label: string;
  interfaceId?: number;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, NumericStat>;
};

export function normalizeInterfacesLine(line: string): NormalizedInterfaceInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const interfaces = Array.isArray(parsed.interfaces) ? parsed.interfaces : [];
  return interfaces.map((entry, index) => normalizeInterfaceEntry(entry, index, time));
}

export function normalizeStreamsLine(line: string): NormalizedStreamInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const interfaces = Array.isArray(parsed.interfaces) ? parsed.interfaces : [];
  const streams = Array.isArray(parsed.streams) ? parsed.streams : [];
  const interfaceNames = interfaceNameMap(interfaces);
  return streams.map((entry) => normalizeStreamEntry(entry, time, interfaceNames)).filter(Boolean) as NormalizedStreamInput[];
}

export function normalizeMetricsLine(line: string): NormalizedMetricInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const metrics = Array.isArray(parsed.metrics) ? parsed.metrics : [];
  return metrics.map((entry) => normalizeMetricEntry(entry, time)).filter(Boolean) as NormalizedMetricInput[];
}

function normalizeInterfaceEntry(entry: AnyRecord, index: number, time: number): NormalizedInterfaceInput {
  const hasMetrics = Boolean(entry?.rx || entry?.tx);
  const rx = normalizeInterfaceCounters(entry?.rx);
  const tx = normalizeInterfaceCounters(entry?.tx);
  const rxRate = normalizeInterfaceRate(entry?.rx?.rate);
  const txRate = normalizeInterfaceRate(entry?.tx?.rate);
  const rxBps = rxRate.bitrateBps ?? statWindow(rx.bytes) * 8;
  const txBps = txRate.bitrateBps ?? statWindow(tx.bytes) * 8;
  const interfaceId = numericId(entry?.interface_id ?? entry?.id);
  const name = String(entry?.name ?? (interfaceId !== undefined ? `if${interfaceId}` : `if${index}`));
  return {
    key: interfaceId !== undefined ? `if:${interfaceId}` : `name:${name}`,
    interfaceId,
    name,
    observed: entry?.observed === true || interfaceId !== undefined,
    available: entry?.available !== false,
    link: normalizeInterfaceLink(entry?.link),
    lastSeen: time,
    rx,
    tx,
    rxRate,
    txRate,
    rxBitrate: { value: rxBps, avg: rxBps, min: rxBps, max: rxBps },
    txBitrate: { value: txBps, avg: txBps, min: txBps, max: txBps },
    rxSparkline: [],
    txSparkline: [],
    hasMetrics
  };
}

function normalizeInterfaceLink(value: AnyRecord | undefined) {
  const speedMbps = finiteNumber(value?.speed_mbps);
  const mtu = finiteNumber(value?.mtu);
  return {
    speedMbps,
    duplex: typeof value?.duplex === "string" ? value.duplex : undefined,
    operstate: typeof value?.operstate === "string" ? value.operstate : undefined,
    carrier: typeof value?.carrier === "boolean" ? value.carrier : undefined,
    mtu,
    mac: typeof value?.mac === "string" ? value.mac : undefined
  };
}

function normalizeInterfaceRate(value: AnyRecord | undefined) {
  return {
    bitrateBps: finiteNumber(value?.bitrate_bps),
    utilization: finiteNumber(value?.utilization),
    headroomBps: finiteNumber(value?.headroom_bps)
  };
}

function normalizeInterfaceCounters(value: AnyRecord | undefined) {
  return {
    bytes: counterStat(value?.bytes),
    packets: counterStat(value?.packets),
    errors: counterStat(value?.errors),
    dropped: counterStat(value?.dropped)
  };
}

function interfaceNameMap(interfaces: AnyRecord[]) {
  const names = new Map<number, string>();
  for (const entry of interfaces) {
    const id = numericId(entry?.interface_id ?? entry?.id);
    if (id !== undefined && entry?.name !== undefined) {
      names.set(id, String(entry.name));
    }
  }
  return names;
}

function counterStat(value: AnyRecord | undefined): NumericStat {
  const current = Number(value?.window ?? value?.value ?? value?.total ?? 0);
  const total = Number(value?.total ?? current);
  return { value: Number.isFinite(current) ? current : 0, avg: Number.isFinite(current) ? current : 0, min: Number.isFinite(current) ? current : 0, max: Number.isFinite(current) ? current : 0, count: Number.isFinite(total) ? total : undefined };
}

function statWindow(stat: NumericStat) {
  return stat.value ?? stat.avg ?? 0;
}

function normalizeStreamEntry(entry: AnyRecord, time: number, interfaceNames: Map<number, string>): NormalizedStreamInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const raw = entry?.stream ?? {};
  const streamKey = String(raw.stream_key ?? entry.stream_key ?? "");
  if (!streamKey) return undefined;
  const interfaceId = numericId(raw.interface_id ?? entry.interface_id ?? interfaceIdFromKey(streamKey));
  const interfaceName = interfaceId !== undefined ? interfaceNames.get(interfaceId) : undefined;

  const rawFlows = Array.isArray(raw.flows) ? raw.flows : [];
  const flows: FlowState[] = rawFlows.length > 0
    ? rawFlows.map((flow: AnyRecord) => normalizeFlowState(flow, time, interfaceId, interfaceName))
    : [defaultFlow(streamKey, proto, raw, time, interfaceId, interfaceName)];

  const endpointA = raw.endpoint?.a;
  const endpointB = raw.endpoint?.b;
  const sessionDst = raw.session_dst;
  const label = proto === "RTP" && sessionDst
    ? `${proto} ${sessionDst}`
    : endpointA && endpointB
      ? `${proto} ${endpointA} ↔ ${endpointB}`
      : streamKey;

  return {
    time,
    stream: {
      streamKey,
      kind: proto,
      proto,
      label,
      endpointA,
      endpointB,
      sessionDst,
      streamId: raw.streamid,
      interfaceId,
      interfaceName,
      active: true,
      lastSeen: Number(raw.last_seen ?? time),
      flowCount: flows.length,
      flowRoles: unique(flows.map((flow) => flow.role)),
      bitrate: {},
      sparkline: [],
      flows
    }
  };
}

function normalizeFlowState(flow: AnyRecord, time: number, parentInterfaceId?: number, parentInterfaceName?: string): FlowState {
  const role = String(flow.role ?? inferRoleFromKey(flow.flow_key) ?? "flow");
  const endpointSrc = flow.endpoint?.src;
  const endpointDst = flow.endpoint?.dst;
  const interfaceId = numericId(flow.interface_id ?? interfaceIdFromKey(flow.flow_key)) ?? parentInterfaceId;
  return {
    flowKey: String(flow.flow_key),
    role,
    label: endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : role,
    interfaceId,
    interfaceName: interfaceId === parentInterfaceId ? parentInterfaceName : undefined,
    endpointSrc,
    endpointDst,
    lastSeen: Number(flow.last_seen ?? time),
    metrics: {}
  };
}

function defaultFlow(streamKey: string, proto: string, raw: AnyRecord, time: number, interfaceId?: number, interfaceName?: string): FlowState {
  const endpointSrc = raw.endpoint?.a;
  const endpointDst = raw.endpoint?.b;
  return {
    flowKey: `${streamKey}|flow=default`,
    role: "default",
    label: endpointSrc && endpointDst ? `${proto}: ${endpointSrc} → ${endpointDst}` : "default",
    interfaceId,
    interfaceName,
    endpointSrc,
    endpointDst,
    lastSeen: Number(raw.last_seen ?? time),
    metrics: {}
  };
}

function normalizeMetricEntry(entry: AnyRecord, time: number): NormalizedMetricInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const streamKey = String(entry?.stream_key ?? "");
  if (!streamKey) return undefined;

  const flowKey = String(entry?.flow_key ?? `${streamKey}|flow=default`);
  const role = String(entry?.role ?? inferRoleFromKey(flowKey) ?? "default");
  const endpointSrc = entry?.endpoint?.src;
  const endpointDst = entry?.endpoint?.dst;
  const label = endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : `${proto} ${role}`;
  const interfaceId = numericId(entry.interface_id ?? interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey));

  return {
    time,
    streamKey,
    flowKey,
    role,
    label,
    interfaceId,
    endpointSrc,
    endpointDst,
    metrics: extractMetrics(entry)
  };
}

function extractMetrics(entry: AnyRecord): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {};
  for (const [key, value] of Object.entries(entry)) {
    if (ignoredMetricKeys.has(key)) continue;
    collectMetric(key, value, metrics);
  }
  return metrics;
}

const ignoredMetricKeys = new Set([
  "proto",
  "stream_key",
  "flow_key",
  "endpoint",
  "role",
  "interface_id",
  "payload_type",
  "ssrc"
]);

function collectMetric(prefix: string, value: unknown, output: Record<string, NumericStat>) {
  if (typeof value === "number" && Number.isFinite(value)) {
    output[prefix] = { value, avg: value, min: value, max: value };
    return;
  }

