stream::stream(const stream_id sid, event_sink &events)
	: m_sid(std::move(sid))
	, m_stream_key(make_stream_key(m_sid))
	, m_session_dst_text(to_string(m_sid.session_dst))
	, m_event_source(json{
		{"proto", "RTP"},
		{"stream_key", m_stream_key},
	})
	, m_events(events) {
}

event_record stream::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event_source,
		.detail = std::move(detail),
	};
}

void stream::emit_detected(double now) {
	m_events.emit(make_event(now, "stream_detected", json{
		{"session_dst", m_session_dst_text},
	}));

	trace(1, "rtp: stream detected %s", m_session_dst_text.c_str());
}

void stream::emit_lost(double now) {
	m_events.emit(make_event(now, "stream_lost", json{
		{"last_seen", last_seen()},
		{"flow_count", m_flows.size()},
	}));

	trace(1, "rtp: stream lost %s", m_session_dst_text.c_str());
}

int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, m_events)).first;
	}

	return it->second->process(i);
}

flow_id stream::resolve_flow_id(const info &i) const {
	const std::uint16_t offset = static_cast<std::uint16_t>(i.dst.port - m_sid.session_dst.port);
	flow_role role = flow_role::unknown;

	switch(offset) {
	case 0: role = flow_role::media; break;
	case 2: role = flow_role::fec_row; break;
	case 4: role = flow_role::fec_col; break;
	default: role = flow_role::unknown; break;
	}

	return make_flow_id(i.interface_id,
	                    role,
	                    i.src.addr, i.src.port,
	                    i.dst.addr, i.dst.port,
	                    i.ssrc,
	                    i.p_type);
}

event_record flow::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event.source,
		.detail = std::move(detail),
	};
}

void flow::update_packet_event(double now,
                               counted_event_state &state,
                               std::uint64_t &count,
                               const char *occurred_type,
                               const char *recovered_type,
                               json detail) {
	const auto event_update = state.update(now, count);

	if(event_update.occurred) {
		detail["window_count"] = event_update.window_count;
		m_events.emit(make_event(now, occurred_type, std::move(detail)));
	}
	if(event_update.recovered) {
		m_events.emit(make_event(now, recovered_type, json{
			{"active_total", event_update.active_total},
		}));
	}

	count = 0;
}

int flow::update_events(double now) {
	update_packet_event(now,
	                    m_event.packet.loss,
	                    m_event.packet.loss_gap_count,
	                    "packet_loss_occurred",
	                    "packet_loss_recovered",
	                    json{
		                    {"gap_count", m_event.packet.loss_gap_count},
		                    {"last_seq", m_metrics.seq_stats.last_seq()},
	                    });
	update_packet_event(now,
	                    m_event.packet.duplicate,
	                    m_event.packet.duplicate_count,
	                    "packet_duplicate_occurred",
	                    "packet_duplicate_recovered",
	                    json{
		                    {"duplicate_count", m_event.packet.duplicate_count},
		                    {"last_seq", m_metrics.seq_stats.last_seq()},
	                    });
	update_packet_event(now,
	                    m_event.packet.reorder,
	                    m_event.packet.reorder_count,
	                    "packet_reorder_occurred",
	                    "packet_reorder_recovered",
	                    json{
		                    {"reorder_count", m_event.packet.reorder_count},
		                    {"last_seq", m_metrics.seq_stats.last_seq()},
