int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid{
		.interface_id = i.interface_id,
		.src = {i.src.addr, i.src.port},
		.dst = {i.dst.addr, i.dst.port}
	};

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, m_events)).first;
	}

	return it->second->process(i);
}

