		    m_hls->append_metrics(tc.r.com.time_epoch, metrics_list);
		    m_other->append_metrics(tc.r.com.time_epoch, metrics_list);
		    json::array_t interface_metrics;
		    m_interfaces->append_metrics(tc.r.com.time_epoch, interface_metrics);

		    json metrics_root{
			    {"time", tc.r.com.time_epoch},
			    {"metrics", std::move(metrics_list)},
			    {"interfaces", std::move(interface_metrics)},
		    };
		    m_writer->dump(metrics_root);

		    json::array_t streams_list;
		    m_srt->append_list(tc.r.com.time_epoch, streams_list);
		    m_rtp->append_list(tc.r.com.time_epoch, streams_list);
		    m_hls->append_list(tc.r.com.time_epoch, streams_list);
