event_sink::event_sink(writer &w)
	: m_writer(w) {
}

//--------------------------------------------------------------------------------
int event_sink::emit(const event_record &e) {
	json j{
		{"time", e.time_epoch},
		{"type", e.type},
	};

	if(e.source.is_null() == false && e.source.empty() == false) {
		j["source"] = e.source;
	}
	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	return m_writer.dump(j);
}

//--------------------------------------------------------------------------------
event_state::event_state(double recovery_retention_sec, bool enable, bool mask)
	: m_enable(enable)
	, m_mask(mask)
	, m_recovery_retention_sec(recovery_retention_sec) {
}

//--------------------------------------------------------------------------------
void event_state::clear() {
	m_active = false;
	m_recovery_pending = false;
	m_recovery_time = 0.0;
}

//--------------------------------------------------------------------------------
bool event_state::occur(double now) {
	(void)now;
	++m_occurred_total;

	if(m_active) {
		return false;
	}

	m_active = true;
	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::recover(double now) {
	if(m_active == false) {
		return false;
	}

	m_active = false;
	m_recovery_time = now;

	if(m_recovery_retention_sec <= 0.0) {
		m_recovery_pending = false;
		return fire();
	}

	m_recovery_pending = true;
	return false;
}

//--------------------------------------------------------------------------------
bool event_state::update(double now) {
	if(m_recovery_pending == false) {
		return false;
	}
	if(m_active) {
		m_recovery_pending = false;
		return false;
	}
	if((now - m_recovery_time) < m_recovery_retention_sec) {
		return false;
	}

	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::remove(double now) {
	(void)now;
	const bool was_active = m_active || m_recovery_pending;
	clear();
	return was_active ? fire() : false;
}

//--------------------------------------------------------------------------------
std::uint64_t event_state::occurred_total_diff() {
	const std::uint64_t diff = m_occurred_total - m_occurred_total_last;
	m_occurred_total_last = m_occurred_total;
	return output_enabled() ? diff : 0;
}

//--------------------------------------------------------------------------------
std::uint64_t event_state::fired_total_diff() {
	const std::uint64_t diff = m_fired_total - m_fired_total_last;
	m_fired_total_last = m_fired_total;
	return output_enabled() ? diff : 0;
}

//--------------------------------------------------------------------------------
bool event_state::fire() {
	if(output_enabled() == false) {
		return false;
	}

	++m_fired_total;
	return true;
}

//--------------------------------------------------------------------------------
counted_event_state::counted_event_state(double recovery_retention_sec,
                                         bool enable,
                                         bool mask)
    : m_state(recovery_retention_sec, enable, mask) {
}

//--------------------------------------------------------------------------------
void counted_event_state::clear() {
    m_state.clear();
    m_active_total = 0;
}

//--------------------------------------------------------------------------------
counted_event_update counted_event_state::update(double now, std::uint64_t window_count) {
    counted_event_update r{};
    r.window_count = window_count;

    if(window_count > 0) {
        m_active_total += window_count;
        if(m_state.occur(now)) {
            r.occurred = true;
            r.active_total = m_active_total;
        }
        return r;
    }

    if(m_state.recover(now)) {
        r.recovered = true;
        r.active_total = m_active_total;
        m_active_total = 0;
        return r;
    }

    if(m_state.update(now)) {
        r.recovered = true;
        r.active_total = m_active_total;
        m_active_total = 0;
    }

    return r;
}

