	}

	m_logger = spdlog::rotating_logger_mt<spdlog::async_factory>(name, file, max_size, max_files);
	m_logger->set_pattern("%v");
	m_logger->set_level(spdlog::level::trace);

	spdlog::flush_every(std::chrono::seconds(interval_sec));

	m_enable = true;
}

