        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  const range = useMemo(() => {
    if (rows.length === 0) {
      return { start: nowSec - 60, end: nowSec, ticks: [nowSec - 60, nowSec - 45, nowSec - 30, nowSec - 15, nowSec] };
    }

    const start = rows.reduce(
