import { Fragment, useEffect, useMemo, useState } from "react";
import type { TimelineRow } from "../types/api";

type TimelinePaneProps = {
  rows: TimelineRow[];
  nowSec: number;
  fadeSec: number;
};

export function TimelinePane({ rows, nowSec, fadeSec }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = false;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = row.interfaceName ?? (row.interfaceId !== undefined ? `if:${row.interfaceId}` : "unknown");
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  const range = useMemo(() => {
    if (rows.length === 0) {
      return { start: nowSec - 60, end: nowSec, ticks: [nowSec - 60, nowSec - 45, nowSec - 30, nowSec - 15, nowSec] };
    }

    const start = rows.reduce(
      (min, row) => Math.min(min, ...row.segments.map((segment) => segment.start)),
      Number.POSITIVE_INFINITY
    );
    const end = rows.reduce(
      (max, row) => Math.max(max, row.lastSeen, ...row.segments.map((segment) => segment.end ?? nowSec)),
      nowSec
    );
    const safeEnd = end > start ? end : start + 1;
    const step = (safeEnd - start) / 4;
    return {
      start,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => start + step * index)
    };
  }, [nowSec, rows]);
  const cursorPercent = percent(nowSec, range.start, range.end);
  const cursorLabel = formatCursor(nowSec);

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => ({
      stream,
      flows: flowsByParent.get(stream.streamKey) ?? []
    }));
  }, [rows]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = item.stream.interfaceName ?? (item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : "unknown");
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
        active: group.rows.some(({ stream }) => stream.active)
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [groupedRows]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
