import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import type { TimelineRow } from "../types/api";

type TimelinePaneProps = {
  rows: TimelineRow[];
  nowSec: number;
  fadeSec: number;
};

export function TimelinePane({ rows, nowSec, fadeSec }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(nowSec);
    }
  }, [isHoveringCursor, nowSec]);

  const updateCursor = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    setCursorSec(range.start + ratio * (range.end - range.start));
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = false;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = row.interfaceName ?? (row.interfaceId !== undefined ? `if:${row.interfaceId}` : "unknown");
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  const range = useMemo(() => {
    if (rows.length === 0) {
      return { start: nowSec - 60, end: nowSec, ticks: [nowSec - 60, nowSec - 45, nowSec - 30, nowSec - 15, nowSec] };
    }

    const start = rows.reduce(
      (min, row) => Math.min(min, ...row.segments.map((segment) => segment.start)),
      Number.POSITIVE_INFINITY
    );
    const end = rows.reduce(
      (max, row) => Math.max(max, row.lastSeen, ...row.segments.map((segment) => segment.end ?? nowSec)),
      nowSec
    );
    const safeEnd = end > start ? end : start + 1;
    const step = (safeEnd - start) / 4;
    return {
      start,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => start + step * index)
    };
  }, [nowSec, rows]);
  const cursorPercent = percent(cursorSec, range.start, range.end);
  const cursorLabel = formatCursor(cursorSec);

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => ({
      stream,
      flows: flowsByParent.get(stream.streamKey) ?? []
    }));
  }, [rows]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = item.stream.interfaceName ?? (item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : "unknown");
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
        active: group.rows.some(({ stream }) => stream.active)
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [groupedRows]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        className="timeline-chart"
        onPointerMove={(event) => {
          setIsHoveringCursor(true);
          updateCursor(event.clientX);
        }}
        onPointerLeave={() => {
          setIsHoveringCursor(false);
          setCursorSec(nowSec);
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label" />
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <div className="timeline-cursor-label" style={{ left: `${clampPercent(cursorPercent)}%` }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="timeline-rows">
        {groupedByInterface.map((group) => (
          <div key={group.key} className="timeline-interface-group">
              <TimelineInterfaceLane
              group={group}
              range={range}
              cursorPercent={clampPercent(cursorPercent)}
              expanded={interfaceExpanded[group.key] ?? true}
              onToggle={() => setInterfaceExpanded((current) => ({ ...current, [group.key]: !(current[group.key] ?? true) }))}
            />
            {(interfaceExpanded[group.key] ?? true) && group.rows.map(({ stream, flows }) => {
              const isExpanded = expanded[stream.streamKey] ?? true;
              return (
                <div key={stream.streamKey} className="timeline-group">
                  <TimelineLane
                    row={stream}
                    range={range}
                    cursorPercent={clampPercent(cursorPercent)}
                    fadeSec={fadeSec}
                    childCount={flows.length}
                    expanded={isExpanded}
                    onToggle={flows.length > 0 ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded })) : undefined}
                  />
                  {isExpanded && flows.map((flow) => (
                    <TimelineLane key={flow.flowKey ?? flow.streamKey} row={flow} range={range} cursorPercent={clampPercent(cursorPercent)} fadeSec={fadeSec} />
                  ))}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

function TimelineInterfaceLane({
  group,
  range,
  cursorPercent,
  expanded,
  onToggle
}: {
  group: {
    key: string;
    label: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    firstSeen: number;
    lastSeen: number;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  expanded: boolean;
  onToggle: () => void;
}) {
  return (
    <div className="timeline-interface-header">
      <div className="timeline-interface-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse interface rows" : "Expand interface rows"}>
            <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
          </button>
          {group.label}
          <em>{group.rows.length}</em>
        </strong>
      </div>
      <div className="timeline-row-track timeline-interface-track">
