        window_ += n;
        total_ += n;
    }

    void add(bool cond) {
        if (cond) {
            inc();
        }
    }

    bool empty() const {
        return window_ == 0;
    }

    std::uint64_t count() const {
        return window_;
    }

    std::uint64_t total() const {
        return total_;
    }

    result value() const {
        return result{ .window = window_, .total = total_ };
    }

private:
