	update_rollup(now, metrics, interfaces);
}

metrics_history_sink::hourly_slot metrics_history_sink::slot_for(double now) {
	auto tm = utc_tm(now);
	return hourly_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
