    };

    void reset() {
        initialized_ = false;
        current_sec_ = 0;
    }

    result update(double time_epoch) {
        result r{};
        const std::int64_t sec = static_cast<std::int64_t>(time_epoch);

        if(!initialized_) {
            initialized_ = true;
            current_sec_ = sec;
            return r;
        }

        if(sec != current_sec_) {
            r.changed = true;
            r.prev_sec = current_sec_;
            r.curr_sec = sec;
            current_sec_ = sec;
        }

        return r;
    }

private:
    bool initialized_{false};
    std::int64_t current_sec_{0};
};

