function metricsQueryForRange(range: string): MetricsRangeQuery {
  const now = Date.now() / 1000;
  const preset = rangePreset(range);
  if (!preset || preset.windowSec <= 300) {
    return { windowSec: 300 };
  }
  return {
    from: now - preset.windowSec,
    to: now,
    resolutionSec: preset.resolutionSec
  };
}

function rangePreset(range: string) {
  switch (range) {
    case "24h":
      return { windowSec: 24 * 3600, resolutionSec: 60 };
    case "12h":
      return { windowSec: 12 * 3600, resolutionSec: 60 };
    case "6h":
      return { windowSec: 6 * 3600, resolutionSec: 60 };
    case "3h":
      return { windowSec: 3 * 3600, resolutionSec: 60 };
    case "1h":
      return { windowSec: 3600, resolutionSec: 60 };
    case "30m":
      return { windowSec: 1800, resolutionSec: 60 };
    case "10m":
      return { windowSec: 600, resolutionSec: 60 };
    case "5m":
    default:
      return { windowSec: 300 };
  }
}

function timelineRangePreset(range: string) {
  switch (range) {
    case "24h":
      return { windowSec: 24 * 3600 };
    case "12h":
      return { windowSec: 12 * 3600 };
    case "6h":
      return { windowSec: 6 * 3600 };
    case "3h":
      return { windowSec: 3 * 3600 };
    case "1h":
      return { windowSec: 3600 };
    case "30m":
      return { windowSec: 1800 };
    case "10m":
      return { windowSec: 600 };
    case "5m":
    default:
      return { windowSec: 300 };
  }
}

function clipTimelineRows(rows: TimelineRow[], from: number, to: number) {
  return rows
    .map((row) => {
      const segments = row.segments
        .map((segment) => {
          const effectiveEnd = segment.end ?? to;
          if (effectiveEnd <= from || segment.start >= to) return undefined;
          return {
            start: Math.max(segment.start, from),
            end: segment.end === null ? null : Math.min(segment.end, to)
          };
        })
        .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

      if (segments.length === 0) {
        return undefined;
      }

      return {
        ...row,
        firstSeen: segments[0].start,
        lastSeen: Math.min(row.lastSeen, to),
        segments
      };
    })
    .filter((row): row is TimelineRow => row !== undefined);
}

function listItemToStreamState(stream: StreamListItem): StreamState {
  return {
    streamKey: stream.streamKey,
    kind: stream.kind,
    proto: stream.proto,
    label: stream.label,
    endpointA: stream.endpointA,
    endpointB: stream.endpointB,
    sessionDst: stream.sessionDst,
    streamId: stream.streamId,
    interfaceId: stream.interfaceId,
    interfaceName: stream.interfaceName,
    active: stream.active,
    lastSeen: stream.lastSeen,
    flowCount: stream.flowCount,
    flowRoles: stream.flowRoles,
    bitrate: stream.bitrate,
    sparkline: stream.sparkline,
    overview: stream.overview,
    flows: stream.flows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      active: flow.active,
      interfaceId: flow.interfaceId,
      interfaceName: flow.interfaceName,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      lastSeen: flow.lastSeen,
      metrics: {}
    }))
  };
}

