stream::stream(const stream_id sid, event_sink &events, timeline_sink &timeline)
	: m_sid(std::move(sid))
	, m_stream_key(make_stream_key(m_sid))
	, m_endpoint_a_text(to_string(m_sid.endpoint_a))
	, m_endpoint_b_text(to_string(m_sid.endpoint_b))
	, m_event_source(json{
		{"proto", "SRT"},
		{"stream_key", m_stream_key},
	})
	, m_events(events)
	, m_timeline(timeline) {
}

event_record stream::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event_source,
		.detail = std::move(detail),
	};
}

void stream::emit_detected(double now) {
	m_events.emit(make_event(now, "stream_detected", json{
		{"endpoint", {
			{"a", m_endpoint_a_text},
			{"b", m_endpoint_b_text},
		}},
		{"streamid", m_sid.streamid},
	}));
	m_timeline.emit(now,
	               "stream_detected",
	               json{
		               {"type", "stream"},
		               {"proto", "SRT"},
		               {"interface_id", m_sid.interface_id},
		               {"stream_key", m_stream_key},
		               {"endpoint", {
			               {"a", m_endpoint_a_text},
			               {"b", m_endpoint_b_text},
		               }},
		               {"streamid", m_sid.streamid},
	               });

	trace(1, "srt: stream detected %s %s %s", m_endpoint_a_text.c_str(), m_endpoint_b_text.c_str(), m_sid.streamid.c_str());
}

void stream::emit_lost(double now) {
	m_events.emit(make_event(now, "stream_lost", json{
		{"last_seen", last_seen()},
		{"flow_count", m_flows.size()},
	}));
	m_timeline.emit(now,
	               "stream_lost",
	               json{
		               {"type", "stream"},
		               {"proto", "SRT"},
		               {"interface_id", m_sid.interface_id},
		               {"stream_key", m_stream_key},
		               {"endpoint", {
			               {"a", m_endpoint_a_text},
			               {"b", m_endpoint_b_text},
		               }},
		               {"streamid", m_sid.streamid},
