    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = row.interfaceName ?? (row.interfaceId !== undefined ? `if:${row.interfaceId}` : "unknown");
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
