    }
    return true;
}

template <class T>
inline bool to_number(std::string_view sv, T& out) {
    static_assert(
        ((std::is_integral_v<T> && !std::is_same_v<T, bool>) ||
         std::is_floating_point_v<T>),
        "T must be non-bool integral or floating point");

    if(sv.empty()) return false;

    // True/False -> 1/0
    if(ieq(sv, "True")) {
        out = static_cast<T>(1);
        return true;
    }
    if(ieq(sv, "False")) {
        out = static_cast<T>(0);
        return true;
    }

    if constexpr (std::is_integral_v<T>) {
        // 16進: 0x12ab / 0X12AB
        if (sv.size() > 2 && sv[0] == '0' && (sv[1] == 'x' || sv[1] == 'X')) {
            auto r = std::from_chars(sv.data() + 2, sv.data() + sv.size(), out, 16);
            return r.ec == std::errc{} && r.ptr == sv.data() + sv.size();
        }

        // 10進
        auto r = std::from_chars(sv.data(), sv.data() + sv.size(), out, 10);
        return r.ec == std::errc{} && r.ptr == sv.data() + sv.size();
    }
    else {
        // 浮動小数
        auto r = std::from_chars(sv.data(), sv.data() + sv.size(), out);
        return r.ec == std::errc{} && r.ptr == sv.data() + sv.size();
    }
}

inline bool to_string(std::string_view sv, std::string &out) {
	out = sv;
	return true;
}

template <class T>
inline bool get_number(const row_t& row, std::size_t idx, T& out) {
    const auto* sv = get_field(row, idx);
    if (!sv) return false;
    return to_number(*sv, out);
}

template <class T>
inline bool get_number(
    const row_t& row,
    const field_map_t& fmap,
    std::string_view name,
    T& out)
{
    const auto* sv = get_field(row, fmap, name);
    if (!sv) return false;
    return to_number(*sv, out);
}

inline bool is_true_sv(std::string_view sv) {
    return sv == "1" || sv == "true" || sv == "True" ||
           sv == "TRUE" || sv == "yes"  || sv == "YES";
}

inline bool get_boolish(const row_t& row, std::size_t idx, bool& out) {
    const auto* sv = get_field(row, idx);
    if (!sv) return false;
    if (sv->empty()) return false;
    out = is_true_sv(*sv);
    return true;
}

inline std::size_t require_index(const field_map_t& fmap, std::string_view name) {
    auto it = fmap.find(std::string(name));
    if (it == fmap.end()) {
        throw std::runtime_error("missing column: " + std::string(name));
    }
    return it->second;
}

} // namespace tsv

