  expanded?: boolean;
  onToggle?: () => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused
    ? " timeline-row-cursor-focused"
    : isHovered
      ? " timeline-row-hovered"
      : "";

  return (
    <div
      className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"}${focusClass}`}
      onPointerEnter={() => onHoverChange(rowKey)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-row-label" title={row.flowKey ?? row.streamKey}>
        <strong>
          {onToggle ? (
            <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse flow rows" : "Expand flow rows"}>
              <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
            </button>
          ) : (
            <span className="timeline-toggle-spacer" aria-hidden="true" />
          )}
          {row.label}
          {childCount > 0 && row.rowType === "stream" ? <em>{childCount}</em> : null}
        </strong>
        {/* <span>{row.rowType === "flow" ? `${row.interfaceName ?? row.kind} / ${row.role ?? "flow"}` : row.interfaceName ?? row.kind}</span> */}
      </div>
      <div className="timeline-row-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {row.segments.map((segment, index) => renderSegment(row, segment, index, range, fadeSec))}
      </div>
    </div>
  );
}

function renderSegment(row: TimelineRow, segment: { start: number; end: number | null }, index: number, range: { start: number; end: number }, fadeSec: number) {
  const fullEnd = segment.end ?? range.end;
  const start = percent(segment.start, range.start, range.end);
  const end = percent(fullEnd, range.start, range.end);
  const width = Math.max(0.6, end - start);
  const baseClass = row.rowType === "flow" ? "timeline-segment-flow" : row.rowType === "stream" ? "timeline-segment-stream" : "timeline-segment-interface";
  const key = `${row.flowKey ?? row.streamKey}:${index}:${segment.start}`;

  if (segment.end === null) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const fadeStart = Math.max(segment.start, fullEnd - fadeSec);
  if (fadeStart <= segment.start + 1e-6) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} timeline-segment-fade active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const solidEnd = percent(fadeStart, range.start, range.end);
  const fadeBegin = percent(fadeStart, range.start, range.end);
  const fadeWidth = Math.max(0.6, end - fadeBegin);

  return (
    <Fragment key={key}>
      <div
        key={`${key}:solid`}
        className={`timeline-segment ${baseClass} timeline-segment-split-solid active`}
        style={{
          left: `${start}%`,
          width: `${Math.max(0.6, solidEnd - start)}%`
        }}
      />
      <div
        key={`${key}:fade`}
        className={`timeline-segment ${baseClass} timeline-segment-fade timeline-segment-split-fade active`}
        style={{
          left: `${fadeBegin}%`,
          width: `${fadeWidth}%`
        }}
      />
    </Fragment>
  );
}

function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function clampPercent(value: number) {
  return Math.min(99.5, Math.max(0.5, value));
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

function formatCursor(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
}

function mergeSegments(segments: Array<{ start: number; end: number }>) {
  if (segments.length === 0) return [];
  const sorted = [...segments].sort((a, b) => a.start - b.start || a.end - b.end);
  const merged = [{ ...sorted[0] }];
  for (let index = 1; index < sorted.length; index += 1) {
    const current = sorted[index];
    const last = merged[merged.length - 1];
    if (current.start <= last.end) {
      last.end = Math.max(last.end, current.end);
    } else {
      merged.push({ ...current });
    }
  }
  return merged;
}

function isOtherLike(row: TimelineRow) {
  const proto = row.proto.toUpperCase();
  return proto !== "RTP" && proto !== "SRT" && proto !== "HLS";
}

function buildOtherProtoGroups(
  rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>,
  scopeKey: string,
  nowSec: number
) {
  const groups = new Map<string, Array<{ stream: TimelineRow; flows: TimelineRow[] }>>();
  for (const item of rows) {
    if (!isOtherLike(item.stream)) continue;
    const proto = item.stream.proto || item.stream.kind || "OTHER";
    const bucket = groups.get(proto) ?? [];
    bucket.push(item);
    groups.set(proto, bucket);
  }

  return [...groups.entries()]
    .map(([proto, grouped]) => ({
      key: `${scopeKey}::${proto}`,
      proto,
      rows: grouped.sort((a, b) => b.stream.lastSeen - a.stream.lastSeen),
      segments: mergeSegments(
        grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec })))
      ),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.proto.localeCompare(b.proto));
}

