.flow-subtitle { color: var(--muted); font-size: 11px; margin-top: 2px; }
.flow-arrow { display: inline-block; margin: 0 4px; color: #a9c9de; font-size: 12px; line-height: 1; }

@media (max-width: 720px) {
  .interface-row { grid-template-columns: 18px 10px minmax(0, 1fr); }
  .interface-headroom { grid-column: 3; justify-self: start; }
  .interface-sparklines { grid-column: 3; justify-self: stretch; width: 100%; }
  .flow-list-row { grid-template-columns: 10px minmax(0, 1fr); }
  .flow-list-row .stream-rate, .flow-list-row .sparkline { grid-column: 2; }
}
.tree-toggle { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 7px; color: var(--muted); transition: transform .16s ease, background .16s ease, color .16s ease; }
.tree-toggle.expandable { background: rgba(255,255,255,.06); color: var(--accent); cursor: pointer; font-size: 20px; line-height: 1; }
.tree-toggle.open { transform: rotate(90deg); background: rgba(102,217,239,.12); }
.flow-list-row.selected { background: rgba(102,217,239,.1); border-color: rgba(102,217,239,.28); }
/* Sharper list treatment */
.hero-panel { border-radius: 16px; }
.list-pane, .detail-pane { border-radius: 16px; }
/*.summary-card, .stat-card { border-radius: 10px; }*/
.summary-card, .stat-card { border-radius: 4px; }

