.interface-title, .interface-subtitle { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.interface-title strong { color: var(--accent); margin-right: 8px; }
.interface-title span, .interface-subtitle { color: var(--muted); font-size: 12px; }
.interface-headroom { display: grid; grid-template-columns: 54px minmax(0, 1fr); align-items: center; gap: 4px; justify-self: end; min-width: 0; }
.interface-headroom strong { display: block; color: #e8eef5; font-size: 13px; line-height: 1; font-variant-numeric: tabular-nums; }
.interface-headroom small { display: block; color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.semi-donut { display: block; overflow: visible; }
.semi-donut-track,
.semi-donut-value { fill: none; stroke-width: 7; stroke-linecap: round; }
.semi-donut-track { stroke: rgba(143,164,188,.22); }
.semi-donut-value { stroke: #7fd4c7; }
.semi-donut-headroom .semi-donut-value { stroke: #7fd4c7; }
.semi-donut-usage .semi-donut-value { stroke: #66d9ef; }
.semi-donut.unknown .semi-donut-track { stroke-dasharray: 4 5; }
.interface-sparklines { display: grid; grid-template-columns: 1fr; gap: 3px; align-items: center; justify-self: end; min-width: 0; width: 270px; padding-left: 12px; }
.interface-rate-row { display: grid; grid-template-columns: 24px 72px 150px; align-items: center; gap: 8px; min-width: 0; justify-content: end; }
.interface-rate-label { color: var(--muted); font-size: 10px; font-weight: 800; letter-spacing: .08em; }
.interface-rate-value { color: #e8eef5; font-size: 11px; font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: right; }
.interface-sparklines .sparkline-empty { width: 150px !important; height: 18px !important; border-radius: 4px; }
.interface-branch { overflow: hidden; display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows .18s ease, opacity .14s ease, margin .18s ease; }
.interface-branch.open { grid-template-rows: 1fr; opacity: 1; margin: 4px 0 8px 18px; }
.interface-branch.closed { grid-template-rows: 0fr; opacity: 0; margin: 0 0 0 18px; }
.interface-branch-inner { min-height: 0; overflow: hidden; }
.proto-tree { margin-top: 4px; }

