  const workspaceRef = useRef<HTMLElement | null>(null);
  const timelineBodyRef = useRef<HTMLDivElement | null>(null);
  const timelineOrderRef = useRef<{ rank: Map<string, number>; next: number }>({ rank: new Map(), next: 0 });
  const timelineSortAppliedTokenRef = useRef(0);
  const initialSplitAppliedRef = useRef({
    width: false,
    leftHeight: false,
    rightHeight: false
  });

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    window.localStorage.setItem("stm-theme", theme);
  }, [theme]);

  useEffect(() => {
    void getAppConfig()
      .then((config) => setAppConfig(config))
      .catch(() => undefined)
      .finally(() => setAppConfigLoaded(true));
  }, []);

  useEffect(() => {
    if (!leftColumnRef.current) return;
    const element = leftColumnRef.current;
    const updateHeight = () => setLeftColumnHeight(element.getBoundingClientRect().height);
    updateHeight();

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!rightColumnRef.current) return;
    const element = rightColumnRef.current;
    const updateHeight = () => setRightColumnHeight(element.getBoundingClientRect().height);
    updateHeight();

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!workspaceRef.current) return;
    const element = workspaceRef.current;
    const updateWidth = () => setWorkspaceWidth(element.clientWidth || element.getBoundingClientRect().width);
    updateWidth();

    const observer = new ResizeObserver(() => updateWidth());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (initialSplitAppliedRef.current.width) return;
    if (workspaceWidth <= 0) return;
    const halfRight = Math.max(MIN_RIGHT_WIDTH, Math.floor((workspaceWidth - 8) / 2));
    setRightPaneWidth(halfRight);
    setRightPaneRestoreWidth(halfRight);
    initialSplitAppliedRef.current.width = true;
  }, [workspaceWidth]);

  useEffect(() => {
    if (initialSplitAppliedRef.current.leftHeight) return;
    if (leftColumnHeight <= 0) return;
    const half = Math.max(MIN_TIMELINE_HEIGHT, Math.floor((leftColumnHeight - 8) / 2));
    setTimelineHeight(half);
    setTimelineRestoreHeight(half);
    initialSplitAppliedRef.current.leftHeight = true;
  }, [leftColumnHeight]);

  useEffect(() => {
    if (initialSplitAppliedRef.current.rightHeight) return;
    if (rightColumnHeight <= 0) return;
    const half = Math.max(MINIMIZED_EVENTS_HEIGHT, Math.floor((rightColumnHeight - 8) / 2));
    setEventsHeight(half);
    setEventsRestoreHeight(half);
    initialSplitAppliedRef.current.rightHeight = true;
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, rightColumnHeight - 8);
    setEventsHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
    setEventsRestoreHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxHeight = Math.max(MIN_TIMELINE_HEIGHT, leftColumnHeight - 8);
    setTimelineHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
    setTimelineRestoreHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
  }, [leftColumnHeight]);

  useEffect(() => {
    const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
    setRightPaneWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
    setRightPaneRestoreWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
  }, [workspaceWidth]);

  const {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedInterface,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
  } = useStreams(
    selectedStreamKey,
    selectedInterfaceKey,
    paused,
    metricsRange,
    timelineRange,
    eventsRange,
    timelineFollowNow,
    manualTimelineWindowEndSec,
    streamSortRefreshToken,
    setSelectedStreamKey
  );
  const loading = !appConfigLoaded || !bootstrapped;

  const filteredStreams = useMemo(() => {
    if (!query.trim()) return streams;
    return streams.filter((stream) =>
      matchesSearch([stream.kind, stream.label, stream.streamKey, stream.interfaceName, stream.flowRoles.join(" "), ...stream.flows.map((flow) => flow.interfaceName)], query)
    );
  }, [streams, query]);

  const filteredTimeline = useMemo(() => {
    const normalized = query.trim().toLowerCase();

    const candidateRows = normalized
      ? (() => {
          const visible = timeline.filter((row) =>
            matchesSearch([row.kind, row.label, row.streamKey, row.flowKey, row.interfaceName, row.role, row.endpointSrc, row.endpointDst], query)
          );
          const visibleKeys = new Set(visible.map(timelineRowKey));
          const parentKeys = new Set(
            visible
              .filter((row) => row.rowType === "flow")
              .map((row) => row.parentStreamKey)
              .filter((value): value is string => Boolean(value))
          );
          return timeline.filter((row) => visibleKeys.has(timelineRowKey(row)) || (row.rowType === "stream" && parentKeys.has(row.streamKey)));
        })()
      : timeline;

    if (timelineSortRefreshToken !== timelineSortAppliedTokenRef.current) {
      const streamOrder = new Map(filteredStreams.map((stream, index) => [stream.streamKey, index]));
      const sorted = [...candidateRows].sort((a, b) => compareTimelineRows(a, b, streamOrder));
      const rank = new Map<string, number>();
      sorted.forEach((row, index) => rank.set(timelineRowKey(row), index));
      timelineOrderRef.current = { rank, next: sorted.length };
      timelineSortAppliedTokenRef.current = timelineSortRefreshToken;
      return sorted;
    }

    return candidateRows;
  }, [filteredStreams, timeline, query, timelineSortRefreshToken]);

  const timelineWindowSec = timelineRangeWindowSec(timelineRange);
  const timelineBrowseSpan = Math.max(timelineWindowSec, timelineAvailable.to - timelineAvailable.from);
  const timelineScrollbarMax = Math.max(0, timelineBrowseSpan - timelineWindowSec);
  const timelineScrollbarValue = Math.max(0, timelineWindow.from - timelineAvailable.from);
  const enableTimelineBrowse = timelineScrollbarMax > 0;
  const timelineWheelStepSec = Math.max(1, Math.round(timelineWindowSec * 0.05));

  useEffect(() => {
    const node = timelineBodyRef.current;
    if (!node) return;

    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey || !enableTimelineBrowse) return;
      event.preventDefault();
      const direction = event.deltaY === 0 ? 0 : event.deltaY > 0 ? 1 : -1;
      if (direction === 0) return;
      setTimelineFollowNow(false);
      setManualTimelineWindowEndSec(timelineWindow.to + direction * timelineWheelStepSec);
    };

    node.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      node.removeEventListener("wheel", onWheel);
    };
  }, [enableTimelineBrowse, timelineWindow.to, timelineWheelStepSec]);

  const detailStream: StreamState | null = selectedStream ?? (selectedListItem
    ? {
        ...selectedListItem,
        flows: selectedListItem.flows.map((flow) => ({
          ...flow,
          metrics: {}
        }))
      }
    : null);

  const eventsMaxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, rightColumnHeight - 8);
  const eventsMinimized = eventsHeight <= MINIMIZED_EVENTS_HEIGHT;
  const eventsMaximized = eventsMaxHeight > MINIMIZED_EVENTS_HEIGHT && eventsHeight >= eventsMaxHeight;
  const eventsRestored = !eventsMinimized && !eventsMaximized;
  const rightColumnRows = eventsMaximized
    ? `0px 8px minmax(0, 1fr)`
    : `minmax(0, 1fr) 8px ${Math.max(MINIMIZED_EVENTS_HEIGHT, eventsHeight)}px`;

  const timelineMaxHeight = Math.max(MIN_TIMELINE_HEIGHT, leftColumnHeight - 8);
  const timelineMinimized = timelineHeight <= MIN_TIMELINE_HEIGHT;
  const timelineMaximized = timelineMaxHeight > MIN_TIMELINE_HEIGHT && timelineHeight >= timelineMaxHeight;
  const timelineRestored = !timelineMinimized && !timelineMaximized;
  const leftColumnRows = timelineMaximized
    ? `auto 0px 8px minmax(0, 1fr)`
    : `auto minmax(0, 1fr) 8px ${Math.max(MIN_TIMELINE_HEIGHT, timelineHeight)}px`;

  const wideLayout = workspaceWidth > 1100;
  const minRightWidth = rightPaneWidth <= COLLAPSED_RIGHT_WIDTH ? COLLAPSED_RIGHT_WIDTH : MIN_RIGHT_WIDTH;
  const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
  const rightPaneMaximized = wideLayout && rightPaneWidth >= maxRightWidth;
  const rightPaneMinimized = !wideLayout || rightPaneWidth <= MIN_RIGHT_WIDTH;
  const listOverviewMode = wideLayout && rightPaneWidth <= COLLAPSED_RIGHT_WIDTH;
  const rightPaneRestored = wideLayout && !rightPaneMaximized && !rightPaneMinimized;
  const workspaceColumns = wideLayout
    ? `minmax(0, 1fr) 8px ${Math.min(maxRightWidth, Math.max(minRightWidth, rightPaneWidth))}px`
    : undefined;

  const startResizeEvents = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const startY = event.clientY;
    const startHeight = eventsHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? rightColumnHeight;
    setRightColumnHeight(columnHeight);
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("height");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, columnHeight - 8);
      const next = Math.min(maxHeight, Math.max(MINIMIZED_EVENTS_HEIGHT, startHeight - (moveEvent.clientY - startY)));
      setEventsHeight(next);
      if (next > MINIMIZED_EVENTS_HEIGHT && next < maxHeight) setEventsRestoreHeight(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const startResizeTimeline = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const startY = event.clientY;
    const startHeight = timelineHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? leftColumnHeight;
    setLeftColumnHeight(columnHeight);
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("height");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxHeight = Math.max(MIN_TIMELINE_HEIGHT, columnHeight - 8);
      const next = Math.min(maxHeight, Math.max(MIN_TIMELINE_HEIGHT, startHeight - (moveEvent.clientY - startY)));
      setTimelineHeight(next);
      if (next > MIN_TIMELINE_HEIGHT && next < maxHeight) setTimelineRestoreHeight(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const startResizeWidth = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!wideLayout) return;
    event.preventDefault();
    event.stopPropagation();
    const startX = event.clientX;
    const startWidth = rightPaneWidth;
    const width = workspaceRef.current?.clientWidth ?? workspaceWidth;
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("width");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxWidth = Math.max(MIN_RIGHT_WIDTH, width - 8);
      const next = Math.min(maxWidth, Math.max(MIN_RIGHT_WIDTH, startWidth - (moveEvent.clientX - startX)));
      setRightPaneWidth(next);
      if (next > MIN_RIGHT_WIDTH && next < maxWidth) setRightPaneRestoreWidth(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  return (
    <main className="app-shell" aria-busy={loading}>
      {loading && (
        <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
          <div className="loading-card">
            <span className="loading-label">Loading...</span>
            <span className="loading-subtext">Waiting for initial stream snapshot</span>
          </div>
        </div>
      )}
      <div className="app-frame">
        <aside className={`menu-rail ${menuExpanded ? "expanded" : "collapsed"}`}>
          <button
            type="button"
            className="menu-rail-toggle"
            onClick={() => setMenuExpanded((current) => !current)}
            aria-pressed={menuExpanded}
            aria-label={menuExpanded ? "Collapse menu" : "Expand menu"}
            title={menuExpanded ? "Collapse menu" : "Expand menu"}
          >
            <span className="menu-rail-toggle-icon" aria-hidden="true">{menuExpanded ? "«" : "»"}</span>
            {menuExpanded && <span className="menu-rail-brand">STM</span>}
          </button>
          <nav className="menu-rail-nav" aria-label="Primary">
            {MENU_ITEMS.map((item) => (
              <button key={item.key} type="button" className={`menu-item ${item.key === "streams" ? "active" : ""}`} title={item.label}>
                <span className="menu-item-icon" aria-hidden="true">{item.icon}</span>
                {menuExpanded && (
                  <span className="menu-item-copy">
                    <strong>{item.label}</strong>
                    <small>{item.hint}</small>
                  </span>
                )}
              </button>
            ))}
          </nav>
        </aside>

        <div className="app-main">
          <section className="hero-panel compact-header">
            <div className="status-strip">
              <button
                type="button"
                className="theme-toggle"
                onClick={() => setTheme((current) => (current === "light" ? "dark" : "light"))}
                title={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
                aria-label={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
              >
                {theme === "light" ? "Dark" : "Light"}
              </button>
              <button
                type="button"
                className={`live-badge live-toggle ${paused ? "paused" : "live"}`}
                onClick={() => setPaused((current) => !current)}
                aria-pressed={paused}
                title={paused ? "Resume live updates" : "Pause display updates"}
              >
                {paused ? "PAUSE" : "LIVE"}
              </button>
              <div>
                <strong>Media Stream Monitor</strong>
                <span>Updated {summary.updatedAt ? formatRelativeTime(summary.updatedAt) : "waiting"} / 5m history{paused ? " / display frozen" : ""}</span>
              </div>
            </div>
            <div className="summary-strip">
              <SummaryCard label="Streams" value={summary.totalStreams.toString()} />
              <SummaryCard label="Active" value={summary.activeStreams.toString()} />
              <SummaryCard label="Kinds" value={Object.keys(summary.byKind).length.toString()} />
              <SummaryCard label="Socket" value={socketState} />
            </div>
          </section>

          <section ref={workspaceRef} className={`workspace workspace-resizable${wideLayout ? " is-wide" : ""}`} style={workspaceColumns ? { gridTemplateColumns: workspaceColumns } : undefined}>
            <aside ref={leftColumnRef} className="list-pane timeline-layout" style={{ gridTemplateRows: leftColumnRows }}>
              <div className="list-toolbar">
                <div className="list-toolbar-header">
                  <div>
                  <h2>Streams</h2>
                  <p>{filteredStreams.length} visible / {streams.length} total</p>
                  </div>
                  <div className="list-toolbar-actions">
                    <button
                      type="button"
                      className="list-sort-refresh-button"
                      onClick={() => setStreamSortRefreshToken((value) => value + 1)}
                      title="Apply latest bitrate sort order"
                    >
                      Sort refresh
                    </button>
                    <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                      <button type="button" className={expandLevel === "interface" ? "active" : ""} onClick={() => setExpandLevel("interface")} aria-pressed={expandLevel === "interface"} title="Show NIC rows only">NIC</button>
                      <button type="button" className={expandLevel === "stream" ? "active" : ""} onClick={() => setExpandLevel("stream")} aria-pressed={expandLevel === "stream"} title="Open NIC rows and show streams">Stream</button>
                      <button type="button" className={expandLevel === "flow" ? "active" : ""} onClick={() => setExpandLevel("flow")} aria-pressed={expandLevel === "flow"} title="Open all NIC, stream, and flow rows">Flow</button>
                    </div>
                    {wideLayout && (
                      <div className="list-width-controls" aria-label="Stream list width controls">
                        <button type="button" className={`size-button size-button-v size-button-left ${rightPaneMaximized ? "active" : ""}`} onClick={() => {
                          const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                          setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
                        }} aria-pressed={rightPaneMaximized} title="Shrink stream list"><span className="width-icon" aria-hidden="true" /></button>
                        <button type="button" className={`size-button size-button-v size-button-center ${rightPaneRestored ? "active" : ""}`} onClick={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))} aria-pressed={rightPaneRestored} title="Restore stream list width"><span className="width-icon" aria-hidden="true" /></button>
                        <button type="button" className={`size-button size-button-v size-button-right ${listOverviewMode ? "active" : ""}`} onClick={() => setRightPaneWidth(COLLAPSED_RIGHT_WIDTH)} aria-pressed={listOverviewMode} title="Maximize stream list"><span className="width-icon" aria-hidden="true" /></button>
                      </div>
                    )}
                  </div>
                </div>
                <label className="search-box">
                  <span aria-hidden="true">⌕</span>
                  <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter by kind, endpoint, role" />
                  {query && (
                    <button type="button" className="search-clear" onClick={() => setQuery("")} aria-label="Clear stream search" title="Clear search">
                      ×
                    </button>
                  )}
                </label>
              </div>
              <StreamTable
                streams={filteredStreams}
                interfaces={interfaces}
                selectedStreamKey={selectedStreamKey}
                selectedFlowKey={selectedFlowKey}
                selectedInterfaceKey={selectedInterfaceKey}
                overviewMode={listOverviewMode}
                expandLevel={expandLevel}
                onSelectInterface={(interfaceKey) => {
                  setSelectedInterfaceKey(interfaceKey);
                  setSelectedStreamKey(null);
                  setSelectedFlowKey(null);
                }}
                onSelectStream={(streamKey) => {
                  setSelectedInterfaceKey(null);
                  setSelectedStreamKey(streamKey);
                  setSelectedFlowKey(null);
                }}
                onSelectFlow={(streamKey, flowKey) => {
                  setSelectedInterfaceKey(null);
                  setSelectedStreamKey(streamKey);
                  setSelectedFlowKey(flowKey);
                }}
              />
              <div className="pane-splitter timeline-splitter" role="separator" aria-orientation="horizontal" onPointerDown={startResizeTimeline} />
              <section className={`timeline-pane${timelineMaximized ? " timeline-maximized" : ""}${timelineMinimized ? " timeline-minimized" : ""}${timelineRestored ? " timeline-restored" : ""}`}>
                <div className="timeline-header">
                  <h3>Timeline</h3>
                  <label className="detail-range-select timeline-range-select">
                    <span>Range</span>
                    <select
                      value={timelineRange}
                      onChange={(event) => {
                        setTimelineRange(event.target.value);
                        if (timelineFollowNow) setManualTimelineWindowEndSec(null);
                      }}
                    >
                      <option value="24h">24h</option>
                      <option value="12h">12h</option>
                      <option value="6h">6h</option>
                      <option value="3h">3h</option>
                      <option value="1h">1h</option>
                      <option value="30m">30m</option>
                      <option value="10m">10m</option>
                      <option value="5m">5m</option>
                    </select>
                  </label>
                  <button
                    type="button"
                    className="list-sort-refresh-button"
                    onClick={() => setTimelineSortRefreshToken((value) => value + 1)}
                    title="Apply latest timeline sort order"
                  >
                    Sort refresh
                  </button>
                  <div className="timeline-browse-controls" title={timelineSource === "history" ? "history" : "live"}>
                    <button
                      type="button"
                      className={timelineFollowNow ? "active" : ""}
                      onClick={() => {
                        setTimelineFollowNow(true);
                        setManualTimelineWindowEndSec(null);
                      }}
                    >
                      Now
                    </button>
                    <button
                      type="button"
                      className={!timelineFollowNow ? "active" : ""}
                      onClick={() => {
                        setTimelineFollowNow(false);
                        setManualTimelineWindowEndSec(timelineWindow.to);
                      }}
                    >
                      Browse
                    </button>
                  </div>
                  <div className="events-size-controls timeline-size-controls" aria-label="Timeline height controls">
                    <button type="button" className={`size-button size-button-min ${timelineMinimized ? "active" : ""}`} onClick={() => setTimelineHeight(MIN_TIMELINE_HEIGHT)} aria-pressed={timelineMinimized} title="Minimize timeline"><span className="height-icon" aria-hidden="true" /></button>
                    <button type="button" className={`size-button size-button-restore ${timelineRestored ? "active" : ""}`} onClick={() => setTimelineHeight(Math.min(timelineMaxHeight, Math.max(MIN_TIMELINE_HEIGHT, timelineRestoreHeight || DEFAULT_TIMELINE_HEIGHT)))} aria-pressed={timelineRestored} title="Restore timeline height"><span className="height-icon" aria-hidden="true" /></button>
                    <button type="button" className={`size-button size-button-max ${timelineMaximized ? "active" : ""}`} onClick={() => setTimelineHeight(timelineMaxHeight)} aria-pressed={timelineMaximized} title="Maximize timeline"><span className="height-icon" aria-hidden="true" /></button>
                  </div>
                </div>
                <div
                  ref={timelineBodyRef}
                  className="timeline-body"
                  title="Ctrl + Wheel: move timeline window"
                >
                  {timelineLoading && (
                    <div className="timeline-loading-overlay" role="status" aria-live="polite" aria-label="Loading timeline">
                      <div className="timeline-loading-dialog">
                        <div className="timeline-loading-spinner" />
                        <span>Loading timeline...</span>
                      </div>
                    </div>
                  )}
                  <TimelinePane
                    rows={filteredTimeline}
                    nowSec={summary.updatedAt ?? Date.now() / 1000}
                    fadeSec={appConfig.lostRetentionSec}
                    rangeStartSec={timelineWindow.from}
                    rangeEndSec={timelineWindow.to}
                  />
                  <div className="timeline-scrollbar">
                    <input
                      type="range"
                      min={0}
                      max={Math.max(1, timelineScrollbarMax)}
                      step={Math.max(1, Math.round(timelineWindowSec / 120))}
                      value={timelineScrollbarMax === 0 ? 0 : timelineScrollbarValue}
                      disabled={!enableTimelineBrowse}
                      onChange={(event) => {
                        const offset = Number(event.target.value);
                        setTimelineFollowNow(false);
                        setManualTimelineWindowEndSec(timelineAvailable.from + offset + timelineWindowSec);
                      }}
                    />
                  </div>
                </div>
              </section>
            </aside>
            <div className="workspace-splitter" role="separator" aria-orientation="vertical" onPointerDown={startResizeWidth} />
            <section ref={rightColumnRef} className={`right-column${eventsMaximized ? " events-maximized" : ""}${eventsMinimized ? " events-minimized" : ""}${listOverviewMode ? " width-collapsed" : ""}`} style={{ gridTemplateRows: rightColumnRows }}>
              {selectedInterface && !selectedStreamKey ? (
                <InterfaceDetailPane
                  item={selectedInterface}
                  metrics={selectedInterfaceMetrics}
                  mode={detailMode}
                  onChangeMode={setDetailMode}
                  onMinimizeWidth={() => setRightPaneWidth(MIN_RIGHT_WIDTH)}
                  onRestoreWidth={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))}
                  onMaximizeWidth={() => {
                    const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                    setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
                  }}
                  isWidthMinimized={rightPaneMinimized}
                  isWidthRestored={rightPaneRestored}
                  isWidthMaximized={rightPaneMaximized}
                  showWidthControls={wideLayout}
                />
              ) : (
                <DetailPane
                  stream={detailStream}
                  metrics={selectedMetrics}
                  selectedFlowKey={selectedFlowKey}
                  metricsRange={metricsRange}
                  onChangeMetricsRange={setMetricsRange}
                  mode={detailMode}
                  onChangeMode={setDetailMode}
                  onMinimizeWidth={() => setRightPaneWidth(MIN_RIGHT_WIDTH)}
                  onRestoreWidth={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))}
                  onMaximizeWidth={() => {
                    const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                    setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
                  }}
                  isWidthMinimized={rightPaneMinimized}
