}

//--------------------------------------------------------------------------------
int event_sink::emit(const event_record &e) {
	json j{
		{"time", e.time_epoch},
		{"type", e.type},
	};

	if(e.source.is_null() == false && e.source.empty() == false) {
		j["source"] = e.source;
	}
	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	const int rc_timeline = emit_timeline(e);
	const int rc_writer = m_writer.dump(j);
	return (rc_writer != 0) ? rc_writer : rc_timeline;
}

//--------------------------------------------------------------------------------
int event_sink::emit_timeline(const event_record &e) {
	if(m_timeline == nullptr) {
		return 0;
	}
	if(e.type != "stream_detected" && e.type != "stream_lost" &&
	   e.type != "flow_detected" && e.type != "flow_lost") {
		return 0;
	}

	json subject = e.source.is_object() ? e.source : json::object();
	json detail = json::object();

	if(e.type.rfind("stream_", 0) == 0) {
		subject["type"] = "stream";
	}
	else {
		subject["type"] = "flow";
	}

	if(e.detail.is_object()) {
		for(const auto &key : {"interface_id", "endpoint", "streamid", "role", "label"}) {
			if(e.detail.contains(key)) {
				subject[key] = e.detail[key];
			}
		}
		for(const auto &key : {"last_seen", "flow_count"}) {
			if(e.detail.contains(key)) {
				detail[key] = e.detail[key];
			}
		}
	}

	return m_timeline->emit(e.time_epoch, e.type, std::move(subject), std::move(detail));
}

