	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst))
	, m_events(events) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.lifetime.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count_total.inc();

	return 0;
}

void flow::emit_detected(double now) {
	m_events.emit(event_record{
		.time_epoch = now,
		.type = "flow_detected",
		.source = [&]() {
			json source{
				{"proto", m_proto},
				{"interface_id", m_fid.interface_id},
				{"stream_key", m_stream_key},
				{"flow_key", m_flow_key},
			};
			if(m_fid.vlan.empty() == false) {
				source["vlan"] = tsv::to_json(m_fid.vlan);
			}
			return source;
		}(),
		.detail = json{
			{"role", "flow"},
			{"endpoint", {
				{"src", m_src_text},
				{"dst", m_dst_text},
			}},
		},
	});
}

void flow::emit_lost(double now) {
	m_events.emit(event_record{
		.time_epoch = now,
		.type = "flow_lost",
		.source = [&]() {
			json source{
				{"proto", m_proto},
				{"interface_id", m_fid.interface_id},
				{"stream_key", m_stream_key},
