bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_default_read_command(file_path, m_protocol_map.decode_as_rules());

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
		return false;
	}

	if(process_tsv(pipe) != 0) {
		std::cerr << "[WARN] parse_tsv failed for " << file_path.filename().string() << std::endl;
	}

	int status = pclose(pipe);
	if(status == -1) {
		std::cerr << "[WARN] pclose failed for " << file_path.filename().string() << std::endl;
		return false;
	}

	if(WIFEXITED(status)) {
		int exit_code = WEXITSTATUS(status);
		if(exit_code == 0) {
			return true;
		}

		std::cerr << "[WARN] tshark failed for " << file_path.filename().string()
		          << ", exit_code=" << exit_code << std::endl;
		return false;
	}

	if(WIFSIGNALED(status)) {
		std::cerr << "[WARN] tshark terminated by signal for "
		          << file_path.filename().string()
		          << ", signal=" << WTERMSIG(status) << std::endl;
		return false;
	}

	std::cerr << "[WARN] tshark ended unexpectedly for "
	          << file_path.filename().string()
	          << ", status=" << status << std::endl;

	return false;
}

int monitor::process_tsv(FILE *pipe) {
	tsv::ctx tc;
	char line[32768];

	m_reorder_buffer.clear();
	m_reorder_seen_any = false;
	m_reorder_latest_seen_time = 0.0;
	m_reorder_seq = 0;

	if(fgets(line, sizeof(line), pipe) != nullptr) {
		tsv::init_ctx(tc, line);
	}

	trace(7, "%s", line);

	while(fgets(line, sizeof(line), pipe) != nullptr) {
		trace(7, "%s", line);

		std::string buffered_line{line};
		tsv::row_t row;
		tsv::split(buffered_line, row);

		double time_epoch = 0.0;
		tsv::to_number(row[tc.i.com.time_epoch], time_epoch);
		m_reorder_buffer.emplace(buffered_row_key{
			                         .time_epoch = time_epoch,
			                         .seq = m_reorder_seq++,
		                         },
		                         std::move(buffered_line));

		if(!m_reorder_seen_any || time_epoch > m_reorder_latest_seen_time) {
			m_reorder_seen_any = true;
			m_reorder_latest_seen_time = time_epoch;
		}

		const double watermark_time = m_reorder_latest_seen_time - m_cfg.reorder_holdback_sec;
		flush_ready_rows(tc, watermark_time);
	}

	flush_all_rows(tc);

	return 0;
}

