/* -*- coding: utf-8 -*- */

#include "logger.h"

#include <time.h>

#include <cstdint>
#include <cstdio>
#include <ctime>
#include <system_error>

#include "spdlog/spdlog.h"
#include "spdlog/async.h"
#include "spdlog/fmt/ostr.h"
#include "spdlog/sinks/basic_file_sink.h"
#include "spdlog/sinks/rotating_file_sink.h"

#include "json.h"
#include "trace.h"

//--------------------------------------------------------------------------------
logger::logger(const char *name, const char *file, size_t max_size, size_t max_files, int interval_sec)
	: m_name(name) {
	m_enable = false;

	{
		std::ofstream ofs(file, std::ios::trunc);
	}

	m_logger = spdlog::rotating_logger_mt<spdlog::async_factory>(name, file, max_size, max_files);
	m_logger->set_pattern("%v");
	m_logger->set_level(spdlog::level::trace);

	spdlog::flush_every(std::chrono::seconds(interval_sec));

	m_enable = true;
}

//--------------------------------------------------------------------------------
logger::~logger() {
	if(m_logger) {
		m_logger->flush();
	}

	spdlog::drop(m_name);
}

//--------------------------------------------------------------------------------
int logger::start() {
	m_enable = true;

	return 0;
}

//--------------------------------------------------------------------------------
int logger::stop() {
	m_enable = false;
	m_logger->flush();

	return 0;
}

//--------------------------------------------------------------------------------
int logger::dump(const json &j) {
	if(!m_enable) {
		return 0;
	}

	m_logger->info(j.dump());

	return 0;
}

//--------------------------------------------------------------------------------
int logger::event(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp(), { "type", "event" } };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

