int monitor::run() {
	switch(m_cfg.input.mode) {
	case input_mode::watch_dir:
		return run_watch_dir();
	case input_mode::file:
		return run_input_file();
	case input_mode::dir:
		return run_input_dir();
	}

	return 1;
}

int monitor::run_watch_dir() {
	if(!m_pcap_watcher) {
		std::cerr << "[ERROR] pcap watcher is not initialized" << std::endl;
		return 1;
	}
	return m_pcap_watcher->run();
}

int monitor::run_input_file() {
	if(m_cfg.input.file.empty()) {
		std::cerr << "[ERROR] input file is not configured" << std::endl;
		return 1;
	}
	return process_pcap(m_cfg.input.file) ? 0 : 1;
}

int monitor::run_input_dir() {
	if(m_cfg.input.dir.empty()) {
		std::cerr << "[ERROR] input dir is not configured" << std::endl;
		return 1;
	}

	auto files = collect_input_pcaps(m_cfg.input.dir);
	if(files.empty()) {
		std::cerr << "[WARN] no pcap files found in " << m_cfg.input.dir << std::endl;
		return 0;
	}

	int rc = 0;
	for(const auto &file : files) {
		if(!process_pcap(file)) {
			rc = 1;
		}
	}
	return rc;
}

std::vector<std::filesystem::path> monitor::collect_input_pcaps(const std::filesystem::path &dir) const {
	std::vector<std::filesystem::path> files;
	for(const auto &entry : std::filesystem::directory_iterator(dir)) {
		if(!entry.is_regular_file()) {
			continue;
		}
		if(is_target_pcap(entry.path())) {
			files.push_back(entry.path());
		}
	}
	std::sort(files.begin(), files.end());
	return files;
}

