inline std::string shell_quote(std::string_view value) {
	std::string quoted;
	quoted.reserve(value.size() + 2);
	quoted.push_back('\'');
	for(char ch : value) {
		if(ch == '\'') {
			quoted += "'\\''";
		}
		else {
			quoted.push_back(ch);
		}
	}
	quoted.push_back('\'');
	return quoted;
}

class command_builder {
public:
	explicit command_builder(std::string program = "tshark")
		: m_program(std::move(program)) {
	}

	command_builder& arg(std::string value) {
		m_args.push_back(std::move(value));
		return *this;
	}

	command_builder& flag(std::string name) {
		m_args.push_back(std::move(name));
		return *this;
	}

	command_builder& option(std::string name, std::string value) {
		m_args.push_back(std::move(name));
		m_args.push_back(std::move(value));
		return *this;
	}

	command_builder& read_file(const std::filesystem::path& path) {
		return option("-r", path.string());
	}

	command_builder& no_name_resolution() {
		return flag("-n");
	}

	command_builder& quiet() {
		return flag("-q");
	}

	command_builder& fields_output() {
		return option("-T", "fields");
	}

	command_builder& header(bool enabled) {
		return option("-E", enabled ? "header=y" : "header=n");
	}

	command_builder& tab_separator() {
		return option("-E", "separator=\t");
	}

	command_builder& field(std::string name) {
		m_args.push_back("-e");
		m_args.push_back(std::move(name));
		return *this;
	}

	command_builder& decode_as(std::string spec) {
		if(std::find(m_decode_as.begin(), m_decode_as.end(), spec) != m_decode_as.end()) {
			return *this;
		}
		m_decode_as.push_back(spec);
		return option("-d", std::move(spec));
	}

	command_builder& disable_protocol(std::string proto) {
		return option("--disable-protocol", std::move(proto));
	}

	command_builder& redirect_stderr_to_devnull() {
		m_redirect_stderr = true;
		return *this;
	}

	std::string build() const {
		std::string command = shell_quote(m_program);
		for(const auto& arg : m_args) {
			command.push_back(' ');
			command += shell_quote(arg);
		}
		if(m_redirect_stderr) {
			command += " 2>/dev/null";
		}
		return command;
	}

private:
	std::string m_program;
	std::vector<std::string> m_args;
	std::vector<std::string> m_decode_as;
	bool m_redirect_stderr{false};
};

