	ok &= require_index(c.h, "srt.rcvrate", c.i.srt.rcvrate);
	ok &= require_index(c.h, "srt.bw", c.i.srt.bw);
	ok &= require_index(c.h, "srt.timestamp", c.i.srt.timestamp);
	ok &= require_index(c.h, "srt.hs.sid", c.i.srt.hs_sid);

