//--------------------------------------------------------------------------------
int event_sink::emit(const event_record &e) {
	int rc = 0;
	for(auto *consumer : m_consumers) {
		if(consumer == nullptr) {
			continue;
		}
		const int consumer_rc = consumer->handle_event(e);
		if(rc == 0 && consumer_rc != 0) {
			rc = consumer_rc;
		}
	}
	return rc;
}

