int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_pcap_source) {
		std::cerr << "[ERROR] pcap input source is not initialized" << std::endl;
		return 1;
	}
	return m_pcap_source->run();
