void metrics_history_sink::observe_entries(std::map<std::string, minute_bucket::subject_accumulator> &accumulators,
                                           const json::array_t &entries,
                                           bool is_interface) {
	for(const auto &entry : entries) {
		if(!entry.is_object()) {
			continue;
		}
		const auto key = subject_key(entry, is_interface);
		auto &acc = accumulators[key];
		if(acc.template_object.is_null()) {
			acc.template_object = make_template(entry);
		}

		std::map<std::string, double> values;
		collect_values("", entry, values);
		for(const auto &[path, sample] : values) {
			acc.stats_by_path[path].add(sample);
			acc.last_by_path[path] = sample;
		}
	}
}

void metrics_history_sink::update_rollup(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	const auto bucket_start = minute_floor(now);
	if(!m_bucket.has_value()) {
		m_bucket = minute_bucket{
			.bucket_start = bucket_start,
			.bucket_end = bucket_start + 60.0,
			.metrics_entries = {},
			.interface_entries = {},
		};
	}
	else if(bucket_start != m_bucket->bucket_start) {
		flush_bucket();
		m_bucket = minute_bucket{
			.bucket_start = bucket_start,
			.bucket_end = bucket_start + 60.0,
			.metrics_entries = {},
			.interface_entries = {},
		};
	}

	observe_entries(m_bucket->metrics_entries, metrics, false);
	observe_entries(m_bucket->interface_entries, interfaces, true);
}

void metrics_history_sink::flush_bucket() {
	if(!m_bucket.has_value()) {
		return;
	}

	const auto slot = slot_for(m_bucket->bucket_start);
	ensure_open(m_rollup_1m_file, "rollup_1m", slot);

	auto build_entries = [](const std::map<std::string, minute_bucket::subject_accumulator> &accumulators) {
		json::array_t out;
		for(const auto &[_, acc] : accumulators) {
			json entry = acc.template_object.is_null() ? json::object() : acc.template_object;
			for(const auto &[path, stats] : acc.stats_by_path) {
				const auto last_it = acc.last_by_path.find(path);
				json stat = {
					{"value", stats.avg()},
					{"avg", stats.avg()},
					{"min", stats.min},
					{"max", stats.max},
					{"count", stats.count},
				};
				if(last_it != acc.last_by_path.end()) {
					stat["last"] = last_it->second;
				}
				set_path(entry, path, std::move(stat));
			}
			out.push_back(std::move(entry));
		}
		return out;
	};

	json root = {
		{"time", m_bucket->bucket_end},
		{"bucket_start", m_bucket->bucket_start},
		{"bucket_end", m_bucket->bucket_end},
		{"resolution_sec", 60},
		{"metrics", build_entries(m_bucket->metrics_entries)},
		{"interfaces", build_entries(m_bucket->interface_entries)},
	};

	write_line(m_rollup_1m_file, root);
	m_bucket.reset();
}

void metrics_history_sink::ensure_open(hourly_file &file, const char *category, const hourly_slot &slot) {
	if(file.stream.is_open() && file.slot == slot) {
		return;
	}

	if(file.stream.is_open()) {
		file.stream.flush();
		file.stream.close();
	}

	file.slot = slot;
	file.path = build_path(m_cfg.root_dir, category, slot);
	std::filesystem::create_directories(file.path.parent_path());
	file.stream.open(file.path, std::ios::app);
}

